INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C1','math',2,2,'u1',2,'천 알아보기 — 100이 10개인 수 1000을 쓰고 「천」으로 읽으며, 999보다 1·990보다 10·900보다 100만큼 더 큰 수로 나타내기',ARRAY['2수01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C2','math',2,2,'u1',3,'몇천 알아보기 — 1000이 몇 개인지로 2000~9000을 쓰고 읽으며, 몇천이 1000이 몇 개인지 거꾸로 알기(천 모형과 백 모형 구별)',ARRAY['2수01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C3','math',2,2,'u1',4,'네 자리 수 쓰고 읽기 — 1000·100·10·1의 개수(수 모형·돈)로 네 자리 수를 쓰고 읽으며, 없는 자리에는 0을 쓰고 0인 자리는 읽지 않기',ARRAY['2수01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C4','math',2,2,'u1',5,'각 자리의 숫자가 나타내는 값 — 천·백·십·일의 자리 숫자를 찾고, 같은 숫자라도 자리에 따라 값이 다름을 알며, 네 자리 수를 (몇천)+(몇백)+(몇십)+(몇)으로 나타내기',ARRAY['2수01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C5','math',2,2,'u1',6,'뛰어 세기 — 1000씩·100씩·10씩·1씩 뛰어 세고 거꾸로 세며, 몇씩 뛰었는지 찾고, 윗자리가 바뀌는 문턱(3990→4000, 4999→5000) 넘기',ARRAY['2수01-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C6','math',2,2,'u1',7,'네 자리 수의 크기 비교 — 천의 자리부터 차례로 견주어 >·<로 나타내고, 셋 가운데 가장 큰/작은 수·수 카드로 만든 수·□에 들어갈 수와 연도의 차례 찾기',ARRAY['2수01-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C7','math',2,2,'u1',9,'수를 여러 가지로 나타내기 — 한 수를 1000·100·10·1의 여러 묶음(100이 몇 개, 돈 바꾸기)으로 나타내고, 한 자리에 10개가 넘게 모이면 윗자리로 바꾸어 세기',ARRAY['2수01-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X01','math',2,'u1',ARRAY['M2-2-u1-C1','M2-2-u1-C5']::text[],'9 다음에 윗자리가 바뀌는 것을 모르고 숫자를 이어 붙인다 — 999 다음을 9910, 900 다음 100을 9100, 3990에서 10 더를 39100','수 모형으로 9개 다음 1개를 더 놓고, 10개가 되면 윗자리 모형 1개로 바꾸는 장면을 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X02','math',2,'u1',ARRAY['M2-2-u1-C1','M2-2-u1-C7']::text[],'100이 10개를 10010이나 200처럼 늘어놓거나, 1000 속에 100이 몇 개 있는지 모른다','백 모형 10개를 쌓아 천 모형 1개와 크기가 같음을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X03','math',2,'u1',ARRAY['M2-2-u1-C2','M2-2-u1-C7']::text[],'1000의 개수를 다른 자리에 쓴다 — 1000이 4개를 1004·400으로, 천 모형 3개를 300으로, 3000을 1000이 30개로','천·백·십·일 칸을 그려 놓고 「1000이 몇 개」는 천의 칸에만 쓰게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X04','math',2,'u1',ARRAY['M2-2-u1-C3','M2-2-u1-C4']::text[],'없는 자리의 0을 빠뜨린다 — 천 3·십 2·일 7을 327로, 「육천삼십오」를 635로','네 칸을 먼저 그리고 빈 칸에 0을 채우는 습관 들이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X05','math',2,'u1',ARRAY['M2-2-u1-C3','M2-2-u1-C4']::text[],'읽은 소리나 각 자리 값을 그대로 이어 쓴다 — 사천삼백오십이를 4000300502로, 4000+300+50+2를 그대로 늘어놓기','네 자리 수는 숫자 네 개 — 칸 하나에 숫자 하나만 들어간다는 것을 수 카드 네 장으로 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X06','math',2,'u1',ARRAY['M2-2-u1-C3']::text[],'자리 순서를 섞어 쓴다 — 천 4·백 3·십 9·일 2를 4932·2934로','「천·백·십·일」을 왼쪽부터 손가락으로 짚으며 숫자를 놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X07','math',2,'u1',ARRAY['M2-2-u1-C1','M2-2-u1-C2','M2-2-u1-C3']::text[],'읽을 때 자리 이름을 빼먹거나 0을 읽는다 — 6035를 「육영삼오」·「육천영백삼십오」, 1000을 「일영영영」','숫자 뒤에 자리 이름(천·백·십)을 붙여 끊어 읽고, 0인 자리는 건너뛰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X08','math',2,'u1',ARRAY['M2-2-u1-C4']::text[],'자리 이름을 헷갈린다 — 오른쪽부터 세어 천의 자리와 일의 자리를 바꾸거나, 백의 자리 숫자를 다른 자리 값으로 읽는다','자릿값 표에 수를 써 넣고 「왼쪽이 천」을 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X09','math',2,'u1',ARRAY['M2-2-u1-C4']::text[],'숫자와 그 숫자가 나타내는 값을 같게 본다 — 5836의 8을 8로, 1111의 네 1을 같은 값으로','「숫자 × 자리」로 값을 말하게 하기 — 8은 백의 자리라서 800') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X10','math',2,'u1',ARRAY['M2-2-u1-C3','M2-2-u1-C7']::text[],'한 자리에 10개가 넘게 모여도 윗자리로 바꾸지 않는다 — 1000이 2개·100이 13개를 21300이나 2300으로','10개씩 묶어 윗자리 모형 하나로 바꾼 뒤 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X11','math',2,'u1',ARRAY['M2-2-u1-C5']::text[],'뛰어 셀 때 다른 자리 숫자를 바꾼다 — 1000씩 뛰는데 백의 자리나 일의 자리를 1 바꿈','「1000씩이면 천의 자리만 움직인다」 — 바뀌는 자리에 색칠하며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X12','math',2,'u1',ARRAY['M2-2-u1-C1','M2-2-u1-C5']::text[],'1·10·100·1000 가운데 얼마만큼인지, 몇씩 뛰었는지를 헷갈리거나 방향을 거꾸로 한다','이웃한 두 수에서 바뀐 자리를 찾아 「그 자리만큼」이라고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X13','math',2,'u1',ARRAY['M2-2-u1-C6']::text[],'낮은 자리부터 견주거나 뒤쪽 숫자에 속는다 — 뒤가 9로 가득한 1999가 2005보다 크다고 한다','두 수를 자릿값 표에 위아래로 써 놓고 천의 자리부터 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X14','math',2,'u1',ARRAY['M2-2-u1-C6']::text[],'>·< 기호의 방향을 거꾸로 쓴다','벌어진 입이 큰 수를 먹는다 — 큰 수 쪽이 벌어진 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X15','math',2,'u1',ARRAY['M2-2-u1-C6','M2-2-u1-C7']::text[],'묻는 말을 거꾸로 읽는다 — 가장 큰↔가장 작은, 오래전↔최근, 더 필요한 수↔전체 수','물음의 「큰·작은·더·오래」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X16','math',2,'u1',ARRAY['M2-2-u1-C6']::text[],'수 카드로 수를 만들 때 높은 자리부터 놓지 않거나 0을 맨 앞에 놓는다','천의 자리부터 차례로 — 가장 작은 수를 만들 때 0은 천의 자리에 못 온다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X17','math',2,'u1',ARRAY['M2-2-u1-C3']::text[],'수를 읽는 말과 물건을 세는 말을 섞는다 — 손수건 1536장을 「천오백삼십육 장」이라고 세거나, 수 1536을 「천오백서른여섯」으로 읽는다','수를 읽을 때는 「삼십육」, 물건을 셀 때는 「서른여섯 장」 — 두 말을 나란히 써 놓고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X18','math',2,'u1',ARRAY['M2-2-u1-C3']::text[],'세 자리 수와 네 자리 수를 가리지 못한다 — 1982를 세 자리 수로 보거나, 100원짜리 10개(1000원)를 세 자리 수로 여긴다','숫자가 몇 개인지 세고, 천의 자리에 0이 아닌 숫자가 있으면 네 자리 수라고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#1','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',1,'mc','auto','독도에서 연날리기 행사가 열려요. 연이 한 상자에 100개씩 10상자 있어요. 연은 모두 몇 개인가요?',ARRAY['M2-2-u1-X02']::text[],true,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"독도에서 연날리기 행사가 열려요. 연이 한 상자에 100개씩 10상자 있어요. 연은 모두 몇 개인가요?","options":[{"t":"1000","correct":true},{"t":"110","mis":"M2-2-u1-X02"},{"t":"10010","mis":"M2-2-u1-X02"}],"explanation":["한 상자에 100개씩이니 100, 200, 300, … 하고 상자마다 100씩 세어요.","10상자를 세면 1000 — 100이 10개이면 1000이에요.","1000은 「천」이라고 읽어요."],"asset":{"type":"blocks4","th":0,"h":10,"t":0,"o":0},"variant_rule":{"alt":[{"stem":"100원짜리 동전 10개는 모두 얼마인가요?","options":[{"t":"1000원","correct":true},{"t":"10010원","mis":"M2-2-u1-X02"},{"t":"110원","mis":"M2-2-u1-X02"}],"explanation":["100원짜리 하나는 100원이에요.","100원이 10개이면 1000원이에요.","100원짜리 10개는 천 원짜리 1장과 같아요."],"asset":{"type":"blocks4","th":0,"h":10,"t":0,"o":0,"unit":"coin"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#2','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',1,'mc','auto','1000원짜리 강치 자석을 사려면 100원짜리 동전을 몇 개 내야 하나요?',ARRAY['M2-2-u1-X02']::text[],true,'{"seq":2,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"1000원짜리 강치 자석을 사려면 100원짜리 동전을 몇 개 내야 하나요?","options":[{"t":"10","correct":true},{"t":"9","mis":"M2-2-u1-X02"},{"t":"100","mis":"M2-2-u1-X02"}],"explanation":["100원짜리 9개는 900원이라 아직 모자라요.","100원짜리 10개를 내야 1000원이에요.","100이 10개 모이면 1000이에요."],"variant_rule":{"alt":[{"stem":"연 1000개를 한 상자에 100개씩 담으면 몇 상자가 되나요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M2-2-u1-X02"},{"t":"1","mis":"M2-2-u1-X02"}],"explanation":["100개씩 담아요 — 100, 200, … 1000.","1000은 100이 10개라서 10상자예요.","상자 수와 연의 수를 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#3','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',1,'mc','auto','1000을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07']::text[],true,'{"seq":3,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"1000을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"천","correct":true},{"t":"일영영영","mis":"M2-2-u1-X07"},{"t":"백십","mis":"M2-2-u1-X07"}],"explanation":["1000은 100이 10개인 수예요.","「천」이라고 읽어요.","숫자를 하나씩 따로 읽지 않아요."],"variant_rule":{"alt":[{"stem":"「천」을 수로 쓰면 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"100","mis":"M2-2-u1-X12"},{"t":"10010","mis":"M2-2-u1-X02"}],"explanation":["「천」은 100이 10개인 수예요.","수로 쓰면 1000이에요.","1 뒤에 0을 세 개 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#4','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',1,'sa','auto','수직선에서 100씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C1","difficulty":1,"kind":"sa","stem":"수직선에서 100씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","answer":["1000"],"explanation":["700, 800, 900 — 큰 눈금 한 칸이 100이에요.","900에서 100을 더 가면 1000이에요.","1000은 900보다 100만큼 더 큰 수예요."],"asset":{"type":"jump_row","cells":[700,800,900,null],"step":100}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#5','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'mc','auto','수 배열표에서 900에서 아래로 한 칸 내려가면 1000이 있어요. 1000은 900보다 얼마만큼 더 큰 수인가요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":5,"concept":"M2-2-u1-C1","difficulty":2,"kind":"mc","stem":"수 배열표에서 900에서 아래로 한 칸 내려가면 1000이 있어요. 1000은 900보다 얼마만큼 더 큰 수인가요?","options":[{"t":"100","correct":true},{"t":"10","mis":"M2-2-u1-X12"},{"t":"1","mis":"M2-2-u1-X12"}],"explanation":["이 수 배열표는 아래로 한 칸 갈 때마다 100씩 커져요.","900에서 아래로 한 칸이니 100 커져서 1000이에요.","그래서 1000은 900보다 100만큼 더 큰 수예요."],"asset":{"type":"numgrid","rows":[[770,780,790,800],[870,880,890,900],[970,980,990,1000]],"name":"수 배열표","top":"→ 10씩 · ↓ 100씩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#6','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'mc','auto','수 배열표에서 980에서 오른쪽으로 두 칸 가면 1000이 있어요. 1000은 980보다 얼마만큼 더 큰 수인가요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":6,"concept":"M2-2-u1-C1","difficulty":2,"kind":"mc","stem":"수 배열표에서 980에서 오른쪽으로 두 칸 가면 1000이 있어요. 1000은 980보다 얼마만큼 더 큰 수인가요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-2-u1-X12"},{"t":"200","mis":"M2-2-u1-X12"}],"explanation":["오른쪽으로 한 칸 갈 때마다 10씩 커져요.","980에서 두 칸이면 10씩 두 번 — 20 커져요.","그래서 1000은 980보다 20만큼 더 큰 수예요."],"asset":{"type":"numgrid","rows":[[770,780,790,800],[870,880,890,900],[970,980,990,1000]],"name":"수 배열표","top":"→ 10씩 · ↓ 100씩"},"variant_rule":{"alt":[{"stem":"수 배열표에서 1000에서 왼쪽으로 다섯 칸 가면 어떤 수가 있을까요?","options":[{"t":"950","correct":true},{"t":"995","mis":"M2-2-u1-X12"},{"t":"500","mis":"M2-2-u1-X12"}],"explanation":["왼쪽으로 한 칸 갈 때마다 10씩 작아져요.","1000에서 10씩 다섯 번 작아지면 950이에요.","한 칸은 1이 아니라 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#7','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'blank','auto','100이 9개, 10이 (        )개이면 1000이에요.',ARRAY['M2-2-u1-X02']::text[],true,'{"seq":7,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"100이 9개, 10이 (        )개이면 1000이에요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X02"},{"t":"100","mis":"M2-2-u1-X02"}],"explanation":["100이 9개이면 900이에요.","900에 10을 10개 더하면 1000이에요.","10이 10개는 100 — 100이 모두 10개가 돼요."],"variant_rule":{"alt":[{"stem":"1000은 990보다 (        )만큼 더 큰 수예요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X12"},{"t":"100","mis":"M2-2-u1-X12"}],"explanation":["990에서 10을 더 뛰면 1000이에요.","그래서 10만큼 커요.","수 배열표에서 오른쪽으로 한 칸(10) 차이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#8','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'ox','auto','1000은 990보다 1만큼 더 큰 수예요.',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":8,"concept":"M2-2-u1-C1","difficulty":2,"kind":"ox","stem":"1000은 990보다 1만큼 더 큰 수예요.","answer":"X","reason_options":[{"t":"990보다 10 커야 1000이니까","correct":true},{"t":"990 바로 다음 수가 1000이니까","mis":"M2-2-u1-X12"}],"mis":"M2-2-u1-X12","explanation":["990 바로 다음 수는 991이에요.","990에서 10을 더 가야 1000이에요.","그래서 틀린 말이에요 — 1000은 990보다 10 커요."],"variant_rule":{"alt":[{"stem":"1000은 999보다 1만큼 더 큰 수예요.","answer":"O","reason_options":[{"t":"999 바로 다음 수가 1000이니까","correct":true},{"t":"999 다음은 9910이니까","mis":"M2-2-u1-X01"}],"explanation":["999에 1을 더하면 일·십·백의 자리가 차례로 넘어가요.","그래서 999 다음 수는 1000이에요.","맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#9','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'match','auto','더해서 1000이 되도록 왼쪽과 오른쪽을 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"match","stem":"더해서 1000이 되도록 왼쪽과 오른쪽을 이어 보세요.","pairs":[{"l":"100이 8개인 수","r":"200"},{"l":"100이 5개인 수","r":"500"},{"l":"100이 3개인 수","r":"700"}],"mis":"M2-2-u1-X02","explanation":["100이 8개면 800 — 200을 더하면 1000이에요.","500에는 500, 300에는 700을 더하면 1000이에요.","100이 모두 10개가 되면 1000이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 더해서 1000이 되도록 왼쪽과 오른쪽을 이어 보세요.","pairs":[{"l":"900","r":"100"},{"l":"600","r":"400"},{"l":"990","r":"10"}],"explanation":["900에 100을 더하면 1000이에요.","600에는 400, 990에는 10을 더하면 1000이에요.","얼마만큼 더해야 하는지 수 배열표로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_basic#10','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',3,'sa','auto','「1이 900개, 100이 (   )개이면 1000이 됩니다.」 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":10,"concept":"M2-2-u1-C1","difficulty":3,"kind":"sa","stem":"「1이 900개, 100이 (   )개이면 1000이 됩니다.」 빈칸에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["1이 900개이면 900이에요.","900에 100을 1개 더하면 1000이에요.","그래서 100이 1개예요."],"variant_rule":{"alt":[{"stem":"「10이 (   )개이면 1000이 됩니다.」 빈칸에 알맞은 수는 얼마인가요?","answer":["100"],"explanation":["10이 10개이면 100이에요.","100이 10개이면 1000이니, 10은 100개가 있어야 해요.","그래서 10이 100개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#1','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',2,'mc','auto','100원짜리 동전이 9개이면 900원이에요. 100원짜리 동전이 10개이면 몇 자리 수가 되나요?',ARRAY['M2-2-u1-X18']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":2,"kind":"mc","stem":"100원짜리 동전이 9개이면 900원이에요. 100원짜리 동전이 10개이면 몇 자리 수가 되나요?","options":[{"t":"네 자리 수","correct":true},{"t":"세 자리 수","mis":"M2-2-u1-X18"},{"t":"두 자리 수","mis":"M2-2-u1-X18"}],"explanation":["100원짜리 10개는 1000원이에요.","1000은 숫자가 넷 — 네 자리 수예요.","900 다음 100을 더하면 세 자리로는 나타낼 수 없어서 천의 자리가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#2','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',2,'error','auto','친구들이 1000에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X12','M2-2-u1-X02']::text[],false,'{"seq":2,"concept":"M2-2-u1-C1","difficulty":2,"kind":"error","stem":"친구들이 1000에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 1000은 990보다 1 큰 수야.","correct":true,"mis_target":"M2-2-u1-X12"},{"t":"준우: 1000은 900보다 100 큰 수야.","mis":"M2-2-u1-X12"},{"t":"라희: 1000은 100이 10개인 수야.","mis":"M2-2-u1-X02"}],"explanation":["1000은 990보다 10 큰 수예요.","준우와 라희는 바르게 말했어요.","그래서 서아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#3','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'mc','auto','수 배열표(오른쪽 10씩, 아래 100씩)에서 880에서 아래로 한 칸, 오른쪽으로 두 칸 가면 어떤 수가 있나요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":3,"concept":"M2-2-u1-C1","difficulty":3,"kind":"mc","stem":"수 배열표(오른쪽 10씩, 아래 100씩)에서 880에서 아래로 한 칸, 오른쪽으로 두 칸 가면 어떤 수가 있나요?","options":[{"t":"1000","correct":true},{"t":"900","mis":"M2-2-u1-X12"},{"t":"990","mis":"M2-2-u1-X12"}],"explanation":["880에서 아래로 한 칸 가면 100 커져서 980이에요.","980에서 오른쪽으로 두 칸 가면 20 커져서 1000이에요.","방향마다 커지는 정도가 달라요 — 아래 100, 오른쪽 10."],"asset":{"type":"numgrid","rows":[[770,780,790,800],[870,880,890,900],[970,980,990,1000]],"name":"수 배열표","top":"→ 10씩 · ↓ 100씩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#4','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'sa','auto','0부터 100씩 뛰어 세었어요. 몇 번 뛰어 세면 1000이 되나요?','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C1","difficulty":3,"kind":"sa","stem":"0부터 100씩 뛰어 세었어요. 몇 번 뛰어 세면 1000이 되나요?","answer":["10","10번"],"explanation":["100, 200, 300, … 하고 100씩 뛰어요.","100씩 10번을 가면 1000이에요.","처음 수 0은 뛴 횟수에 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#5','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'mc','auto','1000을 나타낸 것이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X01']::text[],false,'{"seq":5,"concept":"M2-2-u1-C1","difficulty":3,"kind":"mc","stem":"1000을 나타낸 것이 아닌 것은 어느 것인가요?","options":[{"t":"100이 9개, 10이 9개인 수","correct":true},{"t":"100이 9개, 10이 10개인 수","mis":"M2-2-u1-X02"},{"t":"999보다 1만큼 더 큰 수","mis":"M2-2-u1-X01"}],"explanation":["100이 9개, 10이 9개이면 990이에요.","100이 9개, 10이 10개는 1000, 999보다 1 큰 수도 1000이에요.","그래서 1000이 아닌 것은 「100이 9개, 10이 9개인 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#6','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'mc','auto','1, 10, 100을 써서 1000을 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u1-X02']::text[],false,'{"seq":6,"concept":"M2-2-u1-C1","difficulty":3,"kind":"mc","stem":"1, 10, 100을 써서 1000을 바르게 말한 것은 어느 것인가요?","options":[{"t":"10이 100개이면 1000이에요.","correct":true},{"t":"10이 10개이면 1000이에요.","mis":"M2-2-u1-X02"},{"t":"1이 100개이면 1000이에요.","mis":"M2-2-u1-X02"}],"explanation":["10이 10개는 100, 1이 100개도 100이에요.","1000이 되려면 10은 100개 있어야 해요.","10, 100, 1000은 한 자리씩 10배가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#7','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'ox','auto','1000원짜리 독도 기념품을 사려고 100원짜리 동전 9개를 냈어요. 돈이 꼭 맞아요.',ARRAY['M2-2-u1-X02']::text[],false,'{"seq":7,"concept":"M2-2-u1-C1","difficulty":3,"kind":"ox","stem":"1000원짜리 독도 기념품을 사려고 100원짜리 동전 9개를 냈어요. 돈이 꼭 맞아요.","answer":"X","reason_options":[{"t":"100원짜리 9개는 900원이라 100원이 모자라니까","correct":true},{"t":"9 다음은 10이니까 9개면 충분하니까","mis":"M2-2-u1-X02"}],"mis":"M2-2-u1-X02","explanation":["100원짜리 9개는 900원이에요.","1000원이 되려면 100원짜리가 하나 더 있어야 해요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#8','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',4,'sa','auto','연이 100개씩 든 상자가 7개, 10개씩 묶은 꾸러미가 30개 있어요. 연은 모두 몇 개인가요?','{}'::text[],false,'{"seq":8,"concept":"M2-2-u1-C1","difficulty":4,"kind":"sa","stem":"연이 100개씩 든 상자가 7개, 10개씩 묶은 꾸러미가 30개 있어요. 연은 모두 몇 개인가요?","answer":["1000"],"explanation":["100개씩 7상자는 700개예요.","10개씩 30꾸러미는 300개 — 10이 10개면 100이니까 30개면 300이에요.","700과 300을 모으면 1000개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#9','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',4,'mc','auto','100원짜리 동전 6개와 10원짜리 동전 몇 개가 있어야 1000원이 되나요?',ARRAY['M2-2-u1-X02','M2-2-u1-X12']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":4,"kind":"mc","stem":"100원짜리 동전 6개와 10원짜리 동전 몇 개가 있어야 1000원이 되나요?","options":[{"t":"40","correct":true},{"t":"4","mis":"M2-2-u1-X02"},{"t":"400","mis":"M2-2-u1-X12"}],"explanation":["100원짜리 6개는 600원 — 1000원까지 400원이 더 있어야 해요.","10원짜리 10개가 100원이니 400원은 10원짜리 40개예요.","그래서 40개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L02_challenge#10','math',2,2,'u1','L02','tb_g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',4,'essay','teacher','수 배열표(오른쪽으로 10씩, 아래로 100씩 커져요)에서 1000을 찾는 방법을 두 가지 쓰고, 어떤 규칙을 썼는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C1","difficulty":4,"kind":"essay","stem":"수 배열표(오른쪽으로 10씩, 아래로 100씩 커져요)에서 1000을 찾는 방법을 두 가지 쓰고, 어떤 규칙을 썼는지 설명해 보세요.","answer_guide":{"answer":"예) 900에서 아래로 한 칸 — 아래로 100씩 커지니 1000은 900보다 100 큰 수. 980에서 오른쪽으로 두 칸 — 오른쪽으로 10씩 커지니 1000은 980보다 20 큰 수.","scoring_points":["1000을 찾는 서로 다른 출발 수와 방향을 두 가지 썼는가","아래 100씩·오른쪽 10씩 규칙을 바르게 말했는가","1000이 출발 수보다 얼마만큼 큰지 바르게 썼는가"]},"explanation":["수 배열표는 방향마다 커지는 정도가 달라요.","아래로 한 칸은 100, 오른쪽으로 한 칸은 10이에요.","어느 수에서 출발하든 규칙을 쓰면 1000을 찾을 수 있어요."],"asset":{"type":"numgrid","rows":[[770,780,790,800],[870,880,890,900],[970,980,990,1000]],"name":"수 배열표","top":"→ 10씩 · ↓ 100씩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#1','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',1,'mc','auto','지아가 태극기 4개를 사요. 태극기는 1개에 1000원이에요. 지아가 낸 돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":1,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"지아가 태극기 4개를 사요. 태극기는 1개에 1000원이에요. 지아가 낸 돈은 모두 얼마인가요?","options":[{"t":"4000원","correct":true},{"t":"400원","mis":"M2-2-u1-X03"},{"t":"1004원","mis":"M2-2-u1-X03"}],"explanation":["1000원씩 4번 — 1000, 2000, 3000, 4000이에요.","1000이 4개이면 4000이에요.","4000은 「사천」이라고 읽어요."],"asset":{"type":"blocks4","th":4,"h":0,"t":0,"o":0,"unit":"coin"},"variant_rule":{"alt":[{"stem":"태극기 6개를 사려면 얼마를 내야 하나요? (태극기 1개 1000원)","options":[{"t":"6000원","correct":true},{"t":"600원","mis":"M2-2-u1-X03"},{"t":"1006원","mis":"M2-2-u1-X03"}],"explanation":["1000원씩 6번 세어요.","1000이 6개이면 6000 — 6000원이에요.","6000은 「육천」이라고 읽어요."],"asset":{"type":"blocks4","th":6,"h":0,"t":0,"o":0,"unit":"coin"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#2','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',1,'sa','auto','천 모형 8개가 나타내는 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"천 모형 8개가 나타내는 수를 쓰세요.","answer":["8000"],"explanation":["천 모형 하나는 1000이에요.","1000이 8개이면 8000이에요.","8000은 「팔천」이라고 읽어요."],"asset":{"type":"blocks4","th":8,"h":0,"t":0,"o":0},"variant_rule":{"alt":[{"stem":"천 모형 3개가 나타내는 수를 쓰세요.","answer":["3000"],"explanation":["천 모형 하나는 1000이에요.","1000이 3개이면 3000이에요.","3000은 「삼천」이라고 읽어요."],"asset":{"type":"blocks4","th":3,"h":0,"t":0,"o":0}},{"stem":"천 모형 5개가 나타내는 수를 쓰세요.","answer":["5000"],"explanation":["천 모형 하나는 1000이에요.","1000이 5개이면 5000이에요.","5000은 「오천」이라고 읽어요."],"asset":{"type":"blocks4","th":5,"h":0,"t":0,"o":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#3','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',1,'mc','auto','8000을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X03']::text[],true,'{"seq":3,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"8000을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"팔천","correct":true},{"t":"팔영영영","mis":"M2-2-u1-X07"},{"t":"팔백","mis":"M2-2-u1-X03"}],"explanation":["8000은 1000이 8개인 수예요.","「팔천」이라고 읽어요.","팔백은 800이에요."],"variant_rule":{"alt":[{"stem":"「오천」을 수로 쓰면 무엇인가요?","options":[{"t":"5000","correct":true},{"t":"500","mis":"M2-2-u1-X03"},{"t":"1005","mis":"M2-2-u1-X03"}],"explanation":["「오천」은 1000이 5개인 수예요.","수로 쓰면 5000이에요.","500은 오백이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#4','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',1,'blank','auto','1000이 4개이면 (        )이에요.',ARRAY['M2-2-u1-X03']::text[],false,'{"seq":4,"concept":"M2-2-u1-C2","difficulty":1,"kind":"blank","stem":"1000이 4개이면 (        )이에요.","options":[{"t":"4000","correct":true},{"t":"1004","mis":"M2-2-u1-X03"},{"t":"400","mis":"M2-2-u1-X03"}],"explanation":["1000씩 4번 세어요 — 1000, 2000, 3000, 4000.","1000이 4개이면 4000이에요.","4는 천의 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#5','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'mc','auto','6000은 1000이 몇 개인 수인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":5,"concept":"M2-2-u1-C2","difficulty":2,"kind":"mc","stem":"6000은 1000이 몇 개인 수인가요?","options":[{"t":"6","correct":true},{"t":"60","mis":"M2-2-u1-X03"},{"t":"600","mis":"M2-2-u1-X03"}],"explanation":["1000씩 세어 6000까지 가 보세요.","1000, 2000, … 6000 — 6번이에요.","그래서 6000은 1000이 6개예요."],"variant_rule":{"alt":[{"stem":"9000은 1000이 몇 개인 수인가요?","options":[{"t":"9","correct":true},{"t":"90","mis":"M2-2-u1-X03"},{"t":"900","mis":"M2-2-u1-X03"}],"explanation":["1000씩 세어 9000까지 가 보세요.","9번 세면 9000이에요.","그래서 1000이 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#6','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'mc','auto','1000이 1개씩 많아질 때 수가 어떻게 바뀌는지 생각해요. 3000보다 1000만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":6,"concept":"M2-2-u1-C2","difficulty":2,"kind":"mc","stem":"1000이 1개씩 많아질 때 수가 어떻게 바뀌는지 생각해요. 3000보다 1000만큼 더 큰 수는 무엇인가요?","options":[{"t":"4000","correct":true},{"t":"3100","mis":"M2-2-u1-X12"},{"t":"3001","mis":"M2-2-u1-X12"}],"explanation":["1000이 3개이면 3000이에요.","1000이 하나 더 많아지면 1000이 4개 — 4000이에요.","천의 자리 숫자만 1 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#7','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'match','auto','천 모형의 수와 알맞게 읽은 말을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M2-2-u1-C2","difficulty":2,"kind":"match","stem":"천 모형의 수와 알맞게 읽은 말을 이어 보세요.","pairs":[{"l":"천 모형 8개","r":"팔천"},{"l":"천 모형 3개","r":"삼천"},{"l":"천 모형 5개","r":"오천"}],"mis":"M2-2-u1-X03","explanation":["천 모형 8개는 8000 — 팔천이에요.","3개는 삼천, 5개는 오천이에요.","천 모형은 1000을 나타내요 — 백 모형과 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#8','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'mc','auto','친구의 생일 선물을 5000원만큼 사려고 해요. 1000원짜리 공책만 산다면 몇 권을 살 수 있나요?',ARRAY['M2-2-u1-X03']::text[],false,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":2,"kind":"mc","stem":"친구의 생일 선물을 5000원만큼 사려고 해요. 1000원짜리 공책만 산다면 몇 권을 살 수 있나요?","options":[{"t":"5","correct":true},{"t":"50","mis":"M2-2-u1-X03"},{"t":"500","mis":"M2-2-u1-X03"}],"explanation":["1000원이 5장 있으면 5000원이에요.","공책 1권이 1000원이니 5권을 살 수 있어요.","5000은 1000이 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#9','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'ox','auto','3000은 1000이 2개, 100이 10개인 수예요.',ARRAY['M2-2-u1-X02']::text[],true,'{"seq":9,"concept":"M2-2-u1-C2","difficulty":2,"kind":"ox","stem":"3000은 1000이 2개, 100이 10개인 수예요.","answer":"O","reason_options":[{"t":"1000이 2개는 2000, 100이 10개는 1000이니까","correct":true},{"t":"100이 10개는 10이니까","mis":"M2-2-u1-X02"}],"mis":"M2-2-u1-X02","explanation":["1000이 2개이면 2000이에요.","100이 10개이면 1000 — 2000과 1000을 모으면 3000이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"5000은 1000이 3개, 10이 200개인 수예요.","answer":"O","reason_options":[{"t":"1000이 3개는 3000, 10이 200개는 2000이니까","correct":true},{"t":"5000은 1000이 5개로만 나타낼 수 있으니까","mis":"M2-2-u1-X02"}],"explanation":["1000이 3개는 3000이에요.","10이 100개면 1000이니 10이 200개는 2000이에요.","3000과 2000을 모으면 5000 — 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_basic#10','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C7',3,'sa','auto','3000을 1000과 100을 모두 써서 나타내려고 해요. 1000을 2개 쓰면 100은 몇 개를 써야 하나요?','{}'::text[],true,'{"seq":10,"concept":"M2-2-u1-C7","difficulty":3,"kind":"sa","stem":"3000을 1000과 100을 모두 써서 나타내려고 해요. 1000을 2개 쓰면 100은 몇 개를 써야 하나요?","answer":["10","10개"],"explanation":["1000이 2개이면 2000이에요.","3000까지 1000이 더 있어야 해요 — 100이 10개이면 1000이에요.","그래서 100을 10개 써요."],"variant_rule":{"alt":[{"stem":"6000을 1000과 100을 모두 써서 나타내려고 해요. 1000을 5개 쓰면 100은 몇 개를 써야 하나요?","answer":["10","10개"],"explanation":["1000이 5개이면 5000이에요.","6000까지 1000이 더 있어야 해요 — 100이 10개예요.","그래서 100을 10개 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#1','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',2,'mc','auto','지아가 태극기 값으로 천 원짜리 4장을 냈어요. 이 돈을 모두 100원짜리 동전으로 바꾸면 몇 개인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X02']::text[],false,'{"seq":1,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"지아가 태극기 값으로 천 원짜리 4장을 냈어요. 이 돈을 모두 100원짜리 동전으로 바꾸면 몇 개인가요?","options":[{"t":"40","correct":true},{"t":"4","mis":"M2-2-u1-X03"},{"t":"400","mis":"M2-2-u1-X02"}],"explanation":["천 원짜리 한 장은 100원짜리 10개와 같아요.","천 원짜리 4장은 100원짜리 40개예요.","4000은 100이 40개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#2','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호: 천 모형 3개는 300이야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"하윤: 8000은 「팔천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"시우: 6000은 5000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["천 모형 3개는 1000이 3개 — 3000이에요.","300은 백 모형 3개예요.","그래서 지호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#3','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',3,'mc','auto','5000원만큼 학용품을 사요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],false,'{"seq":3,"concept":"M2-2-u1-C2","difficulty":3,"kind":"mc","stem":"5000원만큼 학용품을 사요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?","options":[{"t":"사인펜과 지우개","correct":true},{"t":"색연필과 필통","mis":"M2-2-u1-X15"},{"t":"연필과 고무찰흙","mis":"M2-2-u1-X12"}],"explanation":["사인펜 4000원과 지우개 1000원 — 1000원 4장과 1장, 모두 5장이에요.","1000원 5장이면 5000원이에요.","색연필과 필통은 7000원, 연필과 고무찰흙은 4000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#4','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',3,'sa','auto','1000이 2개, 100이 10개인 수는 얼마인가요?','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C7","difficulty":3,"kind":"sa","stem":"1000이 2개, 100이 10개인 수는 얼마인가요?","answer":["3000"],"explanation":["100이 10개이면 1000이에요.","그래서 1000이 모두 3개 — 3000이에요.","한 자리에 10개가 모이면 윗자리로 바꿔 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#5','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','5000을 나타낸 것이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],false,'{"seq":5,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"5000을 나타낸 것이 아닌 것은 어느 것인가요?","options":[{"t":"1000이 4개, 100이 1개인 수","correct":true},{"t":"1000이 3개, 10이 200개인 수","mis":"M2-2-u1-X02"},{"t":"1000이 4개, 100이 10개인 수","mis":"M2-2-u1-X10"}],"explanation":["1000이 4개, 100이 1개이면 4100이에요.","1000이 3개와 10이 200개는 3000과 2000, 1000이 4개와 100이 10개는 4000과 1000 — 둘 다 5000이에요.","그래서 5000이 아닌 것은 4100이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#6','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',3,'ox','auto','태극기가 1개에 1000원일 때, 9000원으로 태극기를 9개 살 수 있어요.',ARRAY['M2-2-u1-X03']::text[],false,'{"seq":6,"concept":"M2-2-u1-C2","difficulty":3,"kind":"ox","stem":"태극기가 1개에 1000원일 때, 9000원으로 태극기를 9개 살 수 있어요.","answer":"O","reason_options":[{"t":"1000이 9개이면 9000이니까","correct":true},{"t":"9000은 1000이 90개니까","mis":"M2-2-u1-X03"}],"mis":"M2-2-u1-X03","explanation":["9000은 1000이 9개인 수예요.","태극기 1개가 1000원이니 9개를 살 수 있어요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#7','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',3,'mc','auto','지아는 5000원을 가지고 태극기를 몇 개 샀더니 1000원이 남았어요. 태극기를 몇 개 샀나요? (태극기 1개 1000원)',ARRAY['M2-2-u1-X15']::text[],false,'{"seq":7,"concept":"M2-2-u1-C2","difficulty":3,"kind":"mc","stem":"지아는 5000원을 가지고 태극기를 몇 개 샀더니 1000원이 남았어요. 태극기를 몇 개 샀나요? (태극기 1개 1000원)","options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u1-X15"},{"t":"1","mis":"M2-2-u1-X15"}],"explanation":["5000원은 1000원이 5장이에요.","1000원 1장이 남았으니 4장을 썼어요.","태극기 1개가 1000원이니 4개를 샀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#8','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',4,'sa','auto','천 원짜리 3장과 100원짜리 동전 20개가 있어요. 모두 얼마인가요?','{}'::text[],false,'{"seq":8,"concept":"M2-2-u1-C7","difficulty":4,"kind":"sa","stem":"천 원짜리 3장과 100원짜리 동전 20개가 있어요. 모두 얼마인가요?","answer":["5000","5000원"],"explanation":["천 원짜리 3장은 3000원이에요.","100원짜리 10개가 1000원이니 20개는 2000원이에요.","3000원과 2000원을 모으면 5000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#9','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',4,'mc','auto','셋 가운데 나타내는 수가 다른 하나는 어느 것인가요?',ARRAY['M2-2-u1-X03']::text[],false,'{"seq":9,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"셋 가운데 나타내는 수가 다른 하나는 어느 것인가요?","options":[{"t":"100이 2개인 수","correct":true},{"t":"1이 2000개인 수","mis":"M2-2-u1-X03"},{"t":"1000이 2개인 수","mis":"M2-2-u1-X03"}],"explanation":["1이 2000개이면 2000, 1000이 2개도 2000이에요.","100이 2개는 200이에요.","그래서 다른 하나는 「100이 2개인 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L03_challenge#10','math',2,2,'u1','L03','tb_g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',4,'essay','teacher','6000을 1000과 100을 모두 써서 나타내는 방법을 두 가지 쓰고, 그렇게 나타낼 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C7","difficulty":4,"kind":"essay","stem":"6000을 1000과 100을 모두 써서 나타내는 방법을 두 가지 쓰고, 그렇게 나타낼 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예) 1000이 5개, 100이 10개 / 1000이 4개, 100이 20개 — 100이 10개이면 1000이므로 1000 하나를 100 10개로 바꿀 수 있다.","scoring_points":["1000과 100을 모두 써서 6000이 되는 방법을 두 가지 썼는가","100이 10개이면 1000이라는 것을 까닭으로 썼는가","각 방법의 합이 6000인지 바르게 셈했는가"]},"explanation":["1000 하나는 100 10개와 같아요.","1000을 하나 줄이면 100을 10개 더 써요.","그래서 같은 6000도 여러 가지로 나타낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#1','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',1,'mc','auto','독도의 날 기념 손수건을 1000장 묶음 1개, 100장 묶음 5개, 10장 묶음 3개, 낱장 6장으로 정리했어요. 손수건은 모두 몇 장인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X06']::text[],false,'{"seq":1,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"독도의 날 기념 손수건을 1000장 묶음 1개, 100장 묶음 5개, 10장 묶음 3개, 낱장 6장으로 정리했어요. 손수건은 모두 몇 장인가요?","options":[{"t":"1536","correct":true},{"t":"1000536","mis":"M2-2-u1-X05"},{"t":"1563","mis":"M2-2-u1-X06"}],"explanation":["1000이 1개, 100이 5개, 10이 3개, 1이 6개예요.","천의 자리 1, 백의 자리 5, 십의 자리 3, 일의 자리 6 — 1536이에요.","네 자리 수는 숫자 네 개로 써요."],"asset":{"type":"blocks4","th":1,"h":5,"t":3,"o":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#2','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',1,'mc','auto','1536을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X17']::text[],true,'{"seq":2,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"1536을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"천오백삼십육","correct":true},{"t":"일오삼육","mis":"M2-2-u1-X07"},{"t":"천오백서른여섯","mis":"M2-2-u1-X17"}],"explanation":["숫자 뒤에 자리 이름을 붙여 읽어요 — 천, 오백, 삼십, 육.","1536은 「천오백삼십육」이라고 읽어요.","수를 읽을 때는 「서른여섯」이 아니라 「삼십육」이에요."],"variant_rule":{"alt":[{"stem":"3258을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"삼천이백오십팔","correct":true},{"t":"삼이오팔","mis":"M2-2-u1-X07"},{"t":"삼천이백오팔","mis":"M2-2-u1-X07"}],"explanation":["천의 자리 3, 백의 자리 2, 십의 자리 5, 일의 자리 8이에요.","「삼천이백오십팔」이라고 읽어요.","자리 이름을 빼먹지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#3','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',1,'sa','auto','1000이 4개, 100이 3개, 10이 9개, 1이 2개이면 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"sa","stem":"1000이 4개, 100이 3개, 10이 9개, 1이 2개이면 얼마인가요?","answer":["4392"],"explanation":["1000이 4개는 천의 자리 4, 100이 3개는 백의 자리 3이에요.","10이 9개는 십의 자리 9, 1이 2개는 일의 자리 2 — 4392예요.","4392는 「사천삼백구십이」라고 읽어요."],"variant_rule":{"alt":[{"stem":"1000이 3개, 100이 2개, 10이 5개, 1이 8개이면 얼마인가요?","answer":["3258"],"explanation":["천의 자리 3, 백의 자리 2예요.","십의 자리 5, 일의 자리 8 — 3258이에요.","3258은 「삼천이백오십팔」이라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#4','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3258","correct":true},{"t":"3285","mis":"M2-2-u1-X06"},{"t":"3000200508","mis":"M2-2-u1-X05"}],"explanation":["천 모형 3개, 백 모형 2개, 십 모형 5개, 일 모형 8개예요.","1000이 3개, 100이 2개, 10이 5개, 1이 8개 — 3258이에요.","자리 순서대로 숫자 하나씩 써요."],"asset":{"type":"blocks4","th":3,"h":2,"t":5,"o":8},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"4392","correct":true},{"t":"4329","mis":"M2-2-u1-X06"},{"t":"4000300902","mis":"M2-2-u1-X05"}],"explanation":["천 모형 4개, 백 모형 3개, 십 모형 9개, 일 모형 2개예요.","천·백·십·일의 자리에 4, 3, 9, 2 — 4392예요.","자리 순서대로 숫자 하나씩 써요."],"asset":{"type":"blocks4","th":4,"h":3,"t":9,"o":2}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#5','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'mc','auto','손수건 1536장을 카드 두 장으로 말해요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":5,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"손수건 1536장을 카드 두 장으로 말해요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"1000보다 크고, 2000보다 작아요.","correct":true},{"t":"2000보다 커요.","mis":"M2-2-u1-X13"},{"t":"1000보다 작아요.","mis":"M2-2-u1-X13"}],"explanation":["1536은 천의 자리 숫자가 1이에요.","1000보다는 크고, 천의 자리가 2인 2000보다는 작아요.","천의 자리 숫자를 보면 수가 어디쯤인지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#6','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'sa','auto','1000이 2개, 100이 0개, 10이 5개, 1이 1개인 수는 얼마인가요?','{}'::text[],true,'{"seq":6,"concept":"M2-2-u1-C3","difficulty":2,"kind":"sa","stem":"1000이 2개, 100이 0개, 10이 5개, 1이 1개인 수는 얼마인가요?","answer":["2051"],"explanation":["천의 자리 2, 백의 자리 0이에요.","십의 자리 5, 일의 자리 1 — 2051이에요.","없는 자리(백의 자리)에는 0을 써요."],"variant_rule":{"alt":[{"stem":"1000이 5개, 100이 7개, 10이 0개, 1이 8개인 수는 얼마인가요?","answer":["5708"],"explanation":["천의 자리 5, 백의 자리 7이에요.","십의 자리 0, 일의 자리 8 — 5708이에요.","없는 자리(십의 자리)에는 0을 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#7','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X06']::text[],false,'{"seq":7,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3027","correct":true},{"t":"327","mis":"M2-2-u1-X04"},{"t":"3270","mis":"M2-2-u1-X06"}],"explanation":["천 모형 3개, 백 모형은 없고, 십 모형 2개, 일 모형 7개예요.","백의 자리에 0을 써서 3027이에요.","모형이 없는 자리에는 0을 써야 네 자리 수가 돼요."],"asset":{"type":"blocks4","th":3,"h":0,"t":2,"o":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#8','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'mc','auto','손수건이 1536장 있어요. 물건의 수를 세어 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u1-X17']::text[],false,'{"seq":8,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"손수건이 1536장 있어요. 물건의 수를 세어 바르게 말한 것은 어느 것인가요?","options":[{"t":"천오백서른여섯 장","correct":true},{"t":"천오백삼십육 장","mis":"M2-2-u1-X17"},{"t":"천다섯백서른여섯 장","mis":"M2-2-u1-X17"}],"explanation":["수 1536은 「천오백삼십육」이라고 읽어요.","하지만 물건을 셀 때는 「천오백서른여섯 장」이라고 말해요.","읽는 말과 세는 말을 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#9','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'match','auto','수와 읽은 말을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u1-C3","difficulty":2,"kind":"match","stem":"수와 읽은 말을 알맞게 이어 보세요.","pairs":[{"l":"4392","r":"사천삼백구십이"},{"l":"3258","r":"삼천이백오십팔"},{"l":"2051","r":"이천오십일"}],"mis":"M2-2-u1-X07","explanation":["4392는 사천삼백구십이, 3258은 삼천이백오십팔이에요.","2051은 백의 자리가 0이라 「이천오십일」이에요.","0인 자리는 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_basic#10','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',3,'mc','auto','나는 천 모형 2개와 백 모형 4개를, 짝은 십 모형 8개와 일 모형 1개를 놓았어요. 우리가 함께 만든 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],false,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"나는 천 모형 2개와 백 모형 4개를, 짝은 십 모형 8개와 일 모형 1개를 놓았어요. 우리가 함께 만든 수는 얼마인가요?","options":[{"t":"2481","correct":true},{"t":"2418","mis":"M2-2-u1-X06"},{"t":"24081","mis":"M2-2-u1-X05"}],"explanation":["천 모형 2개, 백 모형 4개, 십 모형 8개, 일 모형 1개를 모두 모아요.","천·백·십·일의 자리에 2, 4, 8, 1 — 2481이에요.","2481은 「이천사백팔십일」이라고 읽어요."],"asset":{"type":"blocks4","th":2,"h":4,"t":8,"o":1}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_challenge#1','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',2,'mc','auto','짝과 함께 수 모형으로 네 자리 수를 만들 때 꼭 놓아야 하는 모형은 무엇인가요?',ARRAY['M2-2-u1-X18']::text[],false,'{"seq":1,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"짝과 함께 수 모형으로 네 자리 수를 만들 때 꼭 놓아야 하는 모형은 무엇인가요?","options":[{"t":"천 모형","correct":true},{"t":"백 모형","mis":"M2-2-u1-X18"},{"t":"일 모형","mis":"M2-2-u1-X18"}],"explanation":["네 자리 수는 천의 자리 숫자가 있어야 해요.","천 모형이 없으면 세 자리 수가 돼요.","백·십·일 모형은 놓지 않으면 그 자리에 0을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
