INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_challenge#3','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','지아는 천 원짜리 3장과 100원짜리 동전 8개를 내고 딸기우유와 바나나우유를 한 개씩 샀어요. 딸기우유는 1700원이에요. 낸 돈에서 딸기우유 값만큼 묶고 남은 돈이 바나나우유 값이에요. 바나나우유는 얼마인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],false,'{"seq":3,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"지아는 천 원짜리 3장과 100원짜리 동전 8개를 내고 딸기우유와 바나나우유를 한 개씩 샀어요. 딸기우유는 1700원이에요. 낸 돈에서 딸기우유 값만큼 묶고 남은 돈이 바나나우유 값이에요. 바나나우유는 얼마인가요?","options":[{"t":"2100원","correct":true},{"t":"3800원","mis":"M2-2-u1-X15"},{"t":"1100원","mis":"M2-2-u1-X12"}],"explanation":["지아가 낸 돈은 3800원이에요.","천 원짜리 1장과 100원짜리 7개(1700원)를 묶으면 천 원짜리 2장과 100원짜리 1개가 남아요.","남은 돈은 2100원 — 바나나우유 값이에요."],"asset":{"type":"blocks4","th":3,"h":8,"t":0,"o":0,"unit":"coin"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_challenge#4','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',3,'error','auto','친구들이 읽은 수를 수로 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04','M2-2-u1-X06']::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":3,"kind":"error","stem":"친구들이 읽은 수를 수로 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"민호: 사천삼백오십이 → 4000300502","correct":true,"mis_target":"M2-2-u1-X05"},{"t":"하린: 이천오십일 → 2051","mis":"M2-2-u1-X04"},{"t":"도윤: 삼천이백오십팔 → 3258","mis":"M2-2-u1-X06"}],"explanation":["사천삼백오십이는 천의 자리 4, 백의 자리 3, 십의 자리 5, 일의 자리 2 — 4352예요.","각 자리 값을 그대로 이어 쓰면 안 돼요.","그래서 민호가 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
