INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_challenge#6','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',3,'ox','auto','1000이 3개, 100이 2개, 10이 5개, 1이 8개인 수는 3258이고 「삼천이백오십팔」이라고 읽어요.',ARRAY['M2-2-u1-X07']::text[],false,'{"seq":6,"concept":"M2-2-u1-C3","difficulty":3,"kind":"ox","stem":"1000이 3개, 100이 2개, 10이 5개, 1이 8개인 수는 3258이고 「삼천이백오십팔」이라고 읽어요.","answer":"O","reason_options":[{"t":"자리마다 숫자 하나씩 쓰고 자리 이름을 붙여 읽었으니까","correct":true},{"t":"네 자리 수는 숫자를 하나씩 따로 읽으니까","mis":"M2-2-u1-X07"}],"mis":"M2-2-u1-X07","explanation":["천·백·십·일의 자리에 3, 2, 5, 8 — 3258이에요.","자리 이름을 붙여 「삼천이백오십팔」이라고 읽어요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_challenge#7','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','마트 광고지에서 4700원짜리 물건을 찾았어요. 천 원짜리와 100원짜리로 꼭 맞게 내려면 어떻게 내야 하나요?',ARRAY['M2-2-u1-X06','M2-2-u1-X03']::text[],false,'{"seq":7,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"마트 광고지에서 4700원짜리 물건을 찾았어요. 천 원짜리와 100원짜리로 꼭 맞게 내려면 어떻게 내야 하나요?","options":[{"t":"천 원짜리 4장, 100원짜리 7개","correct":true},{"t":"천 원짜리 7장, 100원짜리 4개","mis":"M2-2-u1-X06"},{"t":"천 원짜리 47장","mis":"M2-2-u1-X03"}],"explanation":["4700은 1000이 4개, 100이 7개예요.","그래서 천 원짜리 4장과 100원짜리 7개를 내요.","천의 자리 숫자는 천 원짜리, 백의 자리 숫자는 100원짜리 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_challenge#8','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',4,'sa','auto','짝과 함께 놓은 수 모형은 천 모형 2개, 백 모형 4개, 십 모형 8개, 일 모형 1개예요. 여기서 백 모형을 모두 빼면 어떤 수가 되나요?','{}'::text[],false,'{"seq":8,"concept":"M2-2-u1-C3","difficulty":4,"kind":"sa","stem":"짝과 함께 놓은 수 모형은 천 모형 2개, 백 모형 4개, 십 모형 8개, 일 모형 1개예요. 여기서 백 모형을 모두 빼면 어떤 수가 되나요?","answer":["2081"],"explanation":["처음 수는 2481이에요.","백 모형을 모두 빼면 백의 자리는 0이 돼요.","그래서 2081이에요 — 빈 자리에는 0을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_challenge#9','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',4,'mc','auto','1000이 3개, 100이 12개, 10이 4개인 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],false,'{"seq":9,"concept":"M2-2-u1-C3","difficulty":4,"kind":"mc","stem":"1000이 3개, 100이 12개, 10이 4개인 수는 얼마인가요?","options":[{"t":"4240","correct":true},{"t":"31240","mis":"M2-2-u1-X10"},{"t":"3240","mis":"M2-2-u1-X10"}],"explanation":["100이 12개는 1000이 1개와 100이 2개예요.","그래서 1000이 4개, 100이 2개, 10이 4개 — 4240이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔 세요."],"asset":{"type":"blocks4","th":3,"h":12,"t":4,"o":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L04_challenge#10','math',2,2,'u1','L04','tb_g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',4,'essay','teacher','수 1536을 읽을 때와 손수건 1536장을 셀 때 말이 어떻게 다른지 쓰고, 0이 들어 있는 수 2051은 어떻게 읽는지도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":4,"kind":"essay","stem":"수 1536을 읽을 때와 손수건 1536장을 셀 때 말이 어떻게 다른지 쓰고, 0이 들어 있는 수 2051은 어떻게 읽는지도 써 보세요.","answer_guide":{"answer":"수는 「천오백삼십육」, 손수건은 「천오백서른여섯 장」이라고 한다. 2051은 백의 자리가 0이라 그 자리를 읽지 않고 「이천오십일」이라고 읽는다.","scoring_points":["수 읽기(천오백삼십육)와 세기(천오백서른여섯 장)를 바르게 구별했는가","0인 자리는 읽지 않는다고 썼는가","2051을 「이천오십일」로 바르게 읽었는가"]},"explanation":["수를 읽을 때와 물건을 셀 때는 쓰는 말이 달라요.","세는 말은 「하나, 둘, … 서른여섯」을 써요.","0인 자리는 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#1','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',1,'mc','auto','3월에 독도에 간 사람은 5591명이에요. 5591에서 일의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08']::text[],false,'{"seq":1,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"3월에 독도에 간 사람은 5591명이에요. 5591에서 일의 자리 숫자는 무엇인가요?","options":[{"t":"1","correct":true},{"t":"5","mis":"M2-2-u1-X08"},{"t":"9","mis":"M2-2-u1-X08"}],"explanation":["왼쪽부터 천, 백, 십, 일의 자리예요.","5591에서 맨 오른쪽 숫자 1이 일의 자리 숫자예요.","일의 자리 숫자 1은 1을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#2','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',1,'mc','auto','5591에서 십의 자리 숫자 9가 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":2,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"5591에서 십의 자리 숫자 9가 나타내는 값은 얼마인가요?","options":[{"t":"90","correct":true},{"t":"9","mis":"M2-2-u1-X09"},{"t":"900","mis":"M2-2-u1-X08"}],"explanation":["9는 십의 자리 숫자예요.","십의 자리 숫자 9는 10이 9개 — 90을 나타내요.","숫자와 그 숫자가 나타내는 값은 달라요."],"asset":{"type":"place_table","digits":[5,5,9,1],"values":[5000,500,null,1],"mark":"t"},"variant_rule":{"alt":[{"stem":"5836에서 숫자 8이 나타내는 값은 얼마인가요?","options":[{"t":"800","correct":true},{"t":"8","mis":"M2-2-u1-X09"},{"t":"80","mis":"M2-2-u1-X08"}],"explanation":["8은 백의 자리 숫자예요.","백의 자리 숫자 8은 100이 8개 — 800을 나타내요.","자리를 보고 값을 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#3','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',1,'sa','auto','5591 = 5000 + 500 + (   ) + 1 — 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M2-2-u1-C4","difficulty":1,"kind":"sa","stem":"5591 = 5000 + 500 + (   ) + 1 — 빈칸에 알맞은 수는 얼마인가요?","answer":["90"],"explanation":["5591은 1000이 5개, 100이 5개, 10이 9개, 1이 1개예요.","10이 9개는 90이에요.","그래서 5591 = 5000 + 500 + 90 + 1이에요."],"variant_rule":{"alt":[{"stem":"5836 = 5000 + (   ) + 30 + 6 — 빈칸에 알맞은 수는 얼마인가요?","answer":["800"],"explanation":["5836에서 백의 자리 숫자는 8이에요.","백의 자리 숫자 8은 800을 나타내요.","그래서 5836 = 5000 + 800 + 30 + 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#4','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',1,'mc','auto','5836의 자릿값 표예요. 백의 자리 숫자가 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":4,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"5836의 자릿값 표예요. 백의 자리 숫자가 나타내는 값은 얼마인가요?","options":[{"t":"800","correct":true},{"t":"8","mis":"M2-2-u1-X09"},{"t":"8000","mis":"M2-2-u1-X08"}],"explanation":["5836에서 백의 자리 숫자는 8이에요.","백의 자리 숫자 8은 800을 나타내요.","천의 자리 5는 5000, 십의 자리 3은 30, 일의 자리 6은 6이에요."],"asset":{"type":"place_table","digits":[5,8,3,6],"values":[5000,null,30,6],"mark":"h"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#5','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'mc','auto','5591에는 숫자 5가 두 번 있어요. 두 숫자 5가 나타내는 값은 각각 얼마인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"5591에는 숫자 5가 두 번 있어요. 두 숫자 5가 나타내는 값은 각각 얼마인가요?","options":[{"t":"5000과 500","correct":true},{"t":"5와 5","mis":"M2-2-u1-X09"},{"t":"500과 50","mis":"M2-2-u1-X08"}],"explanation":["앞의 5는 천의 자리 숫자라 5000이에요.","뒤의 5는 백의 자리 숫자라 500이에요.","같은 숫자라도 놓인 자리에 따라 값이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#6','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'mc','auto','자릿값 카드 1000, 200, 90, 7을 순서대로 겹쳤어요. 만들어진 수는 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X06']::text[],false,'{"seq":6,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"자릿값 카드 1000, 200, 90, 7을 순서대로 겹쳤어요. 만들어진 수는 무엇인가요?","options":[{"t":"1297","correct":true},{"t":"1000200907","mis":"M2-2-u1-X05"},{"t":"1279","mis":"M2-2-u1-X06"}],"explanation":["카드를 겹치면 1000 위에 200, 90, 7이 차례로 놓여요.","천의 자리 1, 백의 자리 2, 십의 자리 9, 일의 자리 7 — 1297이에요.","1297 = 1000 + 200 + 90 + 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#7','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'mc','auto','3015를 자릿값 카드로 만들어요. 쓸 카드가 없는 자리는 어느 자리인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X08']::text[],false,'{"seq":7,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"3015를 자릿값 카드로 만들어요. 쓸 카드가 없는 자리는 어느 자리인가요?","options":[{"t":"백의 자리","correct":true},{"t":"십의 자리","mis":"M2-2-u1-X04"},{"t":"일의 자리","mis":"M2-2-u1-X08"}],"explanation":["3015는 천의 자리 3, 백의 자리 0, 십의 자리 1, 일의 자리 5예요.","백의 자리 숫자가 0이라서 몇백 카드는 쓰지 않아요.","3015 = 3000 + 10 + 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#8','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'mc','auto','자릿값 카드 찾기 놀이를 해요. 선생님이 2595에서 백의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":8,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"자릿값 카드 찾기 놀이를 해요. 선생님이 2595에서 백의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?","options":[{"t":"500","correct":true},{"t":"5","mis":"M2-2-u1-X09"},{"t":"5000","mis":"M2-2-u1-X08"}],"explanation":["2595에서 백의 자리 숫자는 5예요.","백의 자리 숫자 5는 500을 나타내요.","그래서 500이 적힌 카드를 들어요."],"variant_rule":{"alt":[{"stem":"자릿값 카드 찾기 놀이를 해요. 선생님이 2595에서 일의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?","options":[{"t":"5","correct":true},{"t":"500","mis":"M2-2-u1-X08"},{"t":"50","mis":"M2-2-u1-X08"}],"explanation":["2595에서 일의 자리 숫자는 5예요.","일의 자리 숫자 5는 5를 나타내요.","같은 5라도 백의 자리 5는 500이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#9','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'ox','auto','3819에서 천의 자리 숫자 3은 3000을 나타내요.',ARRAY['M2-2-u1-X09']::text[],true,'{"seq":9,"concept":"M2-2-u1-C4","difficulty":2,"kind":"ox","stem":"3819에서 천의 자리 숫자 3은 3000을 나타내요.","answer":"O","reason_options":[{"t":"천의 자리 숫자 3은 1000이 3개라서","correct":true},{"t":"숫자 3은 언제나 3을 나타내니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["3819에서 3은 천의 자리 숫자예요.","천의 자리 숫자 3은 3000을 나타내요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"3819에서 십의 자리 숫자 1은 1을 나타내요.","answer":"X","reason_options":[{"t":"십의 자리 숫자 1은 10을 나타내니까","correct":true},{"t":"숫자 1은 언제나 1을 나타내니까","mis":"M2-2-u1-X09"}],"explanation":["3819에서 1은 십의 자리 숫자예요.","십의 자리 숫자 1은 10을 나타내요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_basic#10','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',3,'mc','auto','1297의 숫자 순서를 바꾸어 9712를 만들었어요. 숫자 9가 나타내는 값은 어떻게 바뀌었나요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":10,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"1297의 숫자 순서를 바꾸어 9712를 만들었어요. 숫자 9가 나타내는 값은 어떻게 바뀌었나요?","options":[{"t":"90에서 9000으로","correct":true},{"t":"9에서 9000으로","mis":"M2-2-u1-X09"},{"t":"900에서 9000으로","mis":"M2-2-u1-X08"}],"explanation":["1297에서 9는 십의 자리 숫자라 90이에요.","9712에서 9는 천의 자리 숫자라 9000이에요.","숫자의 자리가 바뀌면 나타내는 값도 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#1','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',2,'match','auto','3819에서 각 숫자와 그 숫자가 나타내는 값을 이어 보세요.','{}'::text[],false,'{"seq":1,"concept":"M2-2-u1-C4","difficulty":2,"kind":"match","stem":"3819에서 각 숫자와 그 숫자가 나타내는 값을 이어 보세요.","pairs":[{"l":"천의 자리 숫자 3","r":"3000"},{"l":"십의 자리 숫자 1","r":"10"},{"l":"일의 자리 숫자 9","r":"9"}],"mis":"M2-2-u1-X09","explanation":["천의 자리 숫자 3은 3000이에요.","십의 자리 숫자 1은 10, 일의 자리 숫자 9는 9예요.","백의 자리 숫자 8은 800이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#2','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C3',2,'mc','auto','8729를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X06']::text[],false,'{"seq":2,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"8729를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"팔천칠백이십구","correct":true},{"t":"팔칠이구","mis":"M2-2-u1-X07"},{"t":"칠백팔천이십구","mis":"M2-2-u1-X06"}],"explanation":["높은 자리부터 숫자 뒤에 자리 이름을 붙여 읽어요.","8729는 「팔천칠백이십구」예요.","자리 순서를 바꾸거나 숫자만 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#3','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'sa','auto','수 카드 0, 2, 5, 7을 한 번씩만 써서 백의 자리 숫자가 700을 나타내는 네 자리 수를 만들어요. 만들 수 있는 수는 모두 몇 개인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u1-C4","difficulty":3,"kind":"sa","stem":"수 카드 0, 2, 5, 7을 한 번씩만 써서 백의 자리 숫자가 700을 나타내는 네 자리 수를 만들어요. 만들 수 있는 수는 모두 몇 개인가요?","answer":["4","4개"],"explanation":["백의 자리에는 7을 놓아요.","남은 0, 2, 5에서 0은 천의 자리에 못 와요 — 2705, 2750, 5702, 5720이에요.","그래서 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#4','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'mc','auto','수 카드 0, 2, 5, 7을 한 번씩만 써서 백의 자리 숫자가 700을 나타내는 네 자리 수 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X16']::text[],false,'{"seq":4,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"수 카드 0, 2, 5, 7을 한 번씩만 써서 백의 자리 숫자가 700을 나타내는 네 자리 수 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"5720","correct":true},{"t":"7520","mis":"M2-2-u1-X08"},{"t":"5702","mis":"M2-2-u1-X16"}],"explanation":["백의 자리는 7로 정해져 있어요.","천의 자리에 남은 수 가운데 가장 큰 5, 다음 2, 0 — 5720이에요.","7520은 천의 자리 숫자가 7이라 7000을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#5','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'ox','auto','1111에서 네 숫자 1은 모두 같은 값을 나타내요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"1111에서 네 숫자 1은 모두 같은 값을 나타내요.","answer":"X","reason_options":[{"t":"1이 놓인 자리마다 1000, 100, 10, 1로 값이 다르니까","correct":true},{"t":"숫자가 모두 1이니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["1111에서 천의 자리 1은 1000, 백의 자리 1은 100이에요.","십의 자리 1은 10, 일의 자리 1은 1이에요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#6','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'mc','auto','6653에서 백의 자리 숫자 6이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08']::text[],false,'{"seq":6,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"6653에서 백의 자리 숫자 6이 나타내는 값은 얼마인가요?","options":[{"t":"600","correct":true},{"t":"6000","mis":"M2-2-u1-X08"},{"t":"60","mis":"M2-2-u1-X08"}],"explanation":["6653에는 6이 두 번 있어요.","백의 자리 숫자 6은 600을 나타내요.","천의 자리 6은 6000이에요 — 어느 자리인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#7','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'mc','auto','친구가 칠판에 4352를 쓰고 숫자 하나를 가리켰어요. 그 숫자가 나타내는 값이 50이라면 친구가 가리킨 숫자는 어느 것인가요?',ARRAY['M2-2-u1-X08']::text[],false,'{"seq":7,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"친구가 칠판에 4352를 쓰고 숫자 하나를 가리켰어요. 그 숫자가 나타내는 값이 50이라면 친구가 가리킨 숫자는 어느 것인가요?","options":[{"t":"십의 자리 숫자 5","correct":true},{"t":"백의 자리 숫자 3","mis":"M2-2-u1-X08"},{"t":"일의 자리 숫자 2","mis":"M2-2-u1-X08"}],"explanation":["50은 10이 5개예요.","4352에서 십의 자리 숫자가 5예요.","그래서 십의 자리 숫자 5를 가리켰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#8','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',4,'sa','auto','수 카드 0, 2, 5, 7을 한 번씩만 써서 백의 자리 숫자가 700을 나타내는 네 자리 수 가운데 가장 작은 수를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u1-C4","difficulty":4,"kind":"sa","stem":"수 카드 0, 2, 5, 7을 한 번씩만 써서 백의 자리 숫자가 700을 나타내는 네 자리 수 가운데 가장 작은 수를 쓰세요.","answer":["2705"],"explanation":["백의 자리에 7을 놓아요.","천의 자리에는 0이 올 수 없으니 가장 작은 2, 그다음 0, 5 — 2705예요.","0은 천의 자리에 놓을 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#9','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',4,'mc','auto','천의 자리 숫자는 4000을, 십의 자리 숫자는 0을, 일의 자리 숫자는 9를 나타내요. 백의 자리 숫자는 천의 자리 숫자보다 1 커요. 이 수는 무엇인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X04']::text[],false,'{"seq":9,"concept":"M2-2-u1-C4","difficulty":4,"kind":"mc","stem":"천의 자리 숫자는 4000을, 십의 자리 숫자는 0을, 일의 자리 숫자는 9를 나타내요. 백의 자리 숫자는 천의 자리 숫자보다 1 커요. 이 수는 무엇인가요?","options":[{"t":"4509","correct":true},{"t":"4059","mis":"M2-2-u1-X06"},{"t":"459","mis":"M2-2-u1-X04"}],"explanation":["천의 자리 숫자는 4, 백의 자리 숫자는 4보다 1 큰 5예요.","십의 자리 0, 일의 자리 9 — 4509예요.","0인 자리도 빠뜨리지 않고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L05_challenge#10','math',2,2,'u1','L05','tb_g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',4,'essay','teacher','5591에서 두 숫자 5가 나타내는 값이 다른 까닭을 자리 이름을 넣어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C4","difficulty":4,"kind":"essay","stem":"5591에서 두 숫자 5가 나타내는 값이 다른 까닭을 자리 이름을 넣어 써 보세요.","answer_guide":{"answer":"앞의 5는 천의 자리 숫자라서 5000을, 뒤의 5는 백의 자리 숫자라서 500을 나타낸다. 같은 숫자라도 놓인 자리에 따라 나타내는 값이 다르다.","scoring_points":["두 5의 자리(천의 자리·백의 자리)를 바르게 말했는가","5000과 500을 바르게 썼는가","자리에 따라 값이 달라진다는 까닭을 썼는가"]},"explanation":["한 자리씩 왼쪽으로 갈 때마다 값이 10배씩 커져요.","천의 자리 5는 5000, 백의 자리 5는 500이에요.","숫자의 위치가 값을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_basic#1','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',1,'mc','auto','1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],false,'{"seq":1,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"5167","correct":true},{"t":"4168","mis":"M2-2-u1-X11"},{"t":"4267","mis":"M2-2-u1-X11"}],"explanation":["1000씩 뛰어 세면 천의 자리 숫자만 1씩 커져요.","4167 다음은 5167이에요.","백·십·일의 자리 숫자 1, 6, 7은 그대로예요."],"asset":{"type":"jump_row","cells":[2167,3167,4167,null],"step":1000}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_basic#2','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',1,'sa','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u1-C5","difficulty":1,"kind":"sa","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","answer":["9300"],"explanation":["100씩 뛰어 세면 백의 자리 숫자가 1씩 커져요.","9200 다음은 9300이에요.","천의 자리 숫자 9는 그대로예요."],"asset":{"type":"jump_row","cells":[9000,9100,9200,null],"step":100}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_basic#3','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',1,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11','M2-2-u1-X12']::text[],false,'{"seq":3,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"9930","correct":true},{"t":"9921","mis":"M2-2-u1-X11"},{"t":"9940","mis":"M2-2-u1-X12"}],"explanation":["10씩 뛰어 세면 십의 자리 숫자가 1씩 커져요.","9920 다음은 9930이에요.","일의 자리 숫자는 바뀌지 않아요."],"asset":{"type":"jump_row","cells":[9900,9910,9920,null],"step":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
