INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_basic#6','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'mc','auto','1500, 2500, 3500, 4500, 5500으로 뛰어 세었어요. 얼마씩 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"1500, 2500, 3500, 4500, 5500으로 뛰어 세었어요. 얼마씩 뛰어 세었나요?","options":[{"t":"1000씩","correct":true},{"t":"100씩","mis":"M2-2-u1-X12"},{"t":"500씩","mis":"M2-2-u1-X12"}],"explanation":["1500, 2500, 3500 … 하고 천의 자리 숫자만 1씩 커져요.","천의 자리가 1씩 커지면 1000씩 뛰어 센 거예요.","바뀌는 자리를 보면 몇씩인지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_basic#7','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'sa','auto','9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u1-C5","difficulty":2,"kind":"sa","stem":"9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 얼마인가요?","answer":["9933"],"explanation":["오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요.","9932 오른쪽 칸이니 9933이에요.","9923 아래 칸으로 보아도 10 큰 9933이에요."],"asset":{"type":"numgrid","rows":[[9911,9912,9913,9914],[9921,9922,9923,9924],[9931,9932,null,9934]],"name":"수 배열표","q":[2,2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_basic#8','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'mc','auto','9901부터 9999까지의 수 배열표에서 아래로 한 칸씩 가면 수가 얼마씩 커지나요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":8,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"9901부터 9999까지의 수 배열표에서 아래로 한 칸씩 가면 수가 얼마씩 커지나요?","options":[{"t":"10씩","correct":true},{"t":"1씩","mis":"M2-2-u1-X12"},{"t":"100씩","mis":"M2-2-u1-X12"}],"explanation":["9911 아래는 9921, 그 아래는 9931이에요.","십의 자리 숫자가 1씩 커지니 10씩 커져요.","오른쪽으로는 1씩 커져요."],"asset":{"type":"numgrid","rows":[[9911,9912,9913,9914],[9921,9922,9923,9924],[9931,9932,9933,9934]],"name":"수 배열표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_basic#9','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'ox','auto','100씩 뛰어 세면 백의 자리 숫자가 1씩 커져요.',ARRAY['M2-2-u1-X11']::text[],false,'{"seq":9,"concept":"M2-2-u1-C5","difficulty":2,"kind":"ox","stem":"100씩 뛰어 세면 백의 자리 숫자가 1씩 커져요.","answer":"O","reason_options":[{"t":"100이 하나씩 더해지니 백의 자리가 1씩 커지니까","correct":true},{"t":"뛰어 세면 일의 자리 숫자가 1씩 커지니까","mis":"M2-2-u1-X11"}],"mis":"M2-2-u1-X11","explanation":["3217, 3317, 3417 — 백의 자리 숫자가 2, 3, 4로 커져요.","100씩 뛰면 백의 자리만 1씩 커져요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_basic#10','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',3,'mc','auto','1217부터 1000씩 2번 뛰어 센 다음, 거기서 100씩 3번 뛰어 센 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":10,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"1217부터 1000씩 2번 뛰어 센 다음, 거기서 100씩 3번 뛰어 센 수는 무엇인가요?","options":[{"t":"3517","correct":true},{"t":"3247","mis":"M2-2-u1-X12"},{"t":"6217","mis":"M2-2-u1-X12"}],"explanation":["1217 → 2217 → 3217, 1000씩 2번이에요.","3217 → 3317 → 3417 → 3517, 100씩 3번이에요.","1000씩은 천의 자리, 100씩은 백의 자리가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#1','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',2,'mc','auto','1000씩 뛰어 세면 어느 자리 숫자가 1씩 커지나요?',ARRAY['M2-2-u1-X11']::text[],false,'{"seq":1,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"1000씩 뛰어 세면 어느 자리 숫자가 1씩 커지나요?","options":[{"t":"천의 자리","correct":true},{"t":"백의 자리","mis":"M2-2-u1-X11"},{"t":"일의 자리","mis":"M2-2-u1-X11"}],"explanation":["2167, 3167, 4167 하고 맨 앞 숫자만 바뀌어요.","천의 자리 숫자가 1씩 커져요.","1000씩 뛰면 천의 자리, 100씩 뛰면 백의 자리가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#2','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',2,'sa','auto','1000씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u1-C5","difficulty":2,"kind":"sa","stem":"1000씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","answer":["4167"],"explanation":["1000씩 거꾸로 뛰면 천의 자리 숫자가 1씩 작아져요.","5167 다음은 4167이에요.","백·십·일의 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[7167,6167,5167,null],"step":1000,"dir":"down"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#3','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X12']::text[],false,'{"seq":3,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"4000","correct":true},{"t":"39100","mis":"M2-2-u1-X01"},{"t":"3900","mis":"M2-2-u1-X12"}],"explanation":["3990에서 10을 더 뛰면 십의 자리가 10이 돼요.","십의 자리 10은 백의 자리로, 백의 자리 10은 천의 자리로 넘어가 4000이에요.","숫자를 이어 붙이지 않고 윗자리로 넘겨요."],"asset":{"type":"jump_row","cells":[3970,3980,3990,null],"step":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#4','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','1씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],false,'{"seq":4,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"1씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"5999","correct":true},{"t":"6099","mis":"M2-2-u1-X01"},{"t":"5000","mis":"M2-2-u1-X11"}],"explanation":["6000에서 1 작아지면 일·십·백의 자리가 0이라 천의 자리에서 1을 빌려 와요.","그래서 6000 바로 앞의 수는 5999예요.","6000보다 1 작은 수 — 5999예요."],"asset":{"type":"jump_row","cells":[6002,6001,6000,null],"step":1,"dir":"down"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#5','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','9901부터 9999까지의 수 배열표에서 9950보다 10 큰 수는 9950의 어느 쪽에 있나요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":5,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"9901부터 9999까지의 수 배열표에서 9950보다 10 큰 수는 9950의 어느 쪽에 있나요?","options":[{"t":"바로 아래 칸","correct":true},{"t":"바로 오른쪽 칸","mis":"M2-2-u1-X12"},{"t":"바로 위 칸","mis":"M2-2-u1-X12"}],"explanation":["이 수 배열표는 오른쪽으로 1씩, 아래로 10씩 커져요.","10 큰 수 9960은 9950의 바로 아래 칸에 있어요.","오른쪽 칸은 1 큰 9951이에요."],"asset":{"type":"numgrid","rows":[[9938,9939,9940],[9948,9949,9950],[9958,9959,9960]],"name":"수 배열표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#6','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','세미는 9월에 기부 통장에 2360원이 있었어요. 매달 1000원씩 저금하면 12월에는 얼마가 되나요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"세미는 9월에 기부 통장에 2360원이 있었어요. 매달 1000원씩 저금하면 12월에는 얼마가 되나요?","options":[{"t":"5360원","correct":true},{"t":"2390원","mis":"M2-2-u1-X12"},{"t":"2660원","mis":"M2-2-u1-X12"}],"explanation":["10월 3360원, 11월 4360원, 12월 5360원 — 1000씩 3번 뛰어 세요.","1000씩 뛰면 천의 자리 숫자만 1씩 커져요.","그래서 12월에는 5360원이에요."],"asset":{"type":"jump_row","cells":[2360,3360,4360,null],"step":1000}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#7','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'ox','auto','7869, 7769, 7669, …로 뛰어 세면 100씩 커져요.',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":7,"concept":"M2-2-u1-C5","difficulty":3,"kind":"ox","stem":"7869, 7769, 7669, …로 뛰어 세면 100씩 커져요.","answer":"X","reason_options":[{"t":"백의 자리 숫자가 1씩 작아지니 100씩 작아지니까","correct":true},{"t":"숫자가 바뀌면 언제나 커지는 것이니까","mis":"M2-2-u1-X12"}],"mis":"M2-2-u1-X12","explanation":["7869, 7769, 7669 — 백의 자리 숫자가 8, 7, 6으로 작아져요.","100씩 거꾸로 뛰어 센 거예요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#8','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'sa','auto','어떤 수에서 100씩 4번 뛰어 세었더니 3517이 되었어요. 어떤 수는 얼마인가요?','{}'::text[],false,'{"seq":8,"concept":"M2-2-u1-C5","difficulty":4,"kind":"sa","stem":"어떤 수에서 100씩 4번 뛰어 세었더니 3517이 되었어요. 어떤 수는 얼마인가요?","answer":["3117"],"explanation":["거꾸로 생각해요 — 3517에서 100씩 4번 거꾸로 뛰어 세요.","3417, 3317, 3217, 3117이에요.","그래서 어떤 수는 3117이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#9','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'mc','auto','1500부터 1000씩 뛰어 셀 때 9000보다 큰 수가 처음 나오는 것은 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X11']::text[],false,'{"seq":9,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"1500부터 1000씩 뛰어 셀 때 9000보다 큰 수가 처음 나오는 것은 무엇인가요?","options":[{"t":"9500","correct":true},{"t":"8500","mis":"M2-2-u1-X13"},{"t":"9600","mis":"M2-2-u1-X11"}],"explanation":["1500, 2500, … 8500, 9500 하고 천의 자리 숫자만 커져요.","8500은 9000보다 작고, 그다음 9500이 처음으로 9000보다 커요.","9600은 1000씩 뛰어 세어 나오는 수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L06_challenge#10','math',2,2,'u1','L06','tb_g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'essay','teacher','4517에서 1217까지 거꾸로 뛰어 세려고 해요. 1000씩과 100씩을 섞어 내 방법으로 뛰어 센 수를 차례로 쓰고, 어떻게 뛰었는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"4517에서 1217까지 거꾸로 뛰어 세려고 해요. 1000씩과 100씩을 섞어 내 방법으로 뛰어 센 수를 차례로 쓰고, 어떻게 뛰었는지 설명해 보세요.","answer_guide":{"answer":"예) 4517 → 3517(1000씩 거꾸로) → 3417 → 3317 → 3217(100씩 거꾸로 3번) → 2217 → 1217(1000씩 거꾸로 2번).","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","1000씩·100씩 뛰었을 때 바뀌는 자리를 말했는가","거꾸로 뛰면 숫자가 1씩 작아진다고 설명했는가"]},"explanation":["1000씩 거꾸로 뛰면 천의 자리, 100씩 거꾸로 뛰면 백의 자리가 1씩 작아져요.","4517에서 1217까지는 천의 자리 3, 백의 자리 3이 작아져야 해요.","어떤 순서로 뛰어도 바르게 세면 1217에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#1','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','독도에서 발견된 생물 종류의 수는 2015년에 1422종, 2024년에 2180종이에요. 생물 종류의 수가 더 많았던 해는 언제인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":1,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"독도에서 발견된 생물 종류의 수는 2015년에 1422종, 2024년에 2180종이에요. 생물 종류의 수가 더 많았던 해는 언제인가요?","options":[{"t":"2024년","correct":true},{"t":"2015년","mis":"M2-2-u1-X13"},{"t":"두 해가 같아요","mis":"M2-2-u1-X13"}],"explanation":["1422와 2180의 천의 자리 숫자를 견주어요 — 1과 2예요.","천의 자리 숫자가 큰 2180이 더 커요.","그래서 2024년에 더 많았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#2','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','1422와 2180의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],false,'{"seq":2,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"1422와 2180의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"1422 < 2180","correct":true},{"t":"1422 > 2180","mis":"M2-2-u1-X14"}],"explanation":["천의 자리 숫자 1은 2보다 작아요.","그래서 1422는 2180보다 작아요 — 1422 < 2180.","벌어진 쪽이 큰 수를 향해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#3','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','네 자리 수의 크기를 비교할 때 가장 먼저 견주는 자리는 어디인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":3,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"네 자리 수의 크기를 비교할 때 가장 먼저 견주는 자리는 어디인가요?","options":[{"t":"천의 자리","correct":true},{"t":"일의 자리","mis":"M2-2-u1-X13"},{"t":"백의 자리","mis":"M2-2-u1-X13"}],"explanation":["세 자리 수를 견줄 때처럼 맨 앞 자리부터 견주어요.","네 자리 수는 천의 자리부터 견주어요.","천의 자리 수가 같으면 백의 자리, 그다음 십의 자리 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#4','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','5107과 5400 가운데 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":4,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"5107과 5400 가운데 더 큰 수는 무엇인가요?","options":[{"t":"5400","correct":true},{"t":"5107","mis":"M2-2-u1-X13"}],"explanation":["천의 자리 숫자는 5로 같아요.","백의 자리 숫자 4가 1보다 커서 5400이 더 커요.","천의 자리가 같으면 백의 자리를 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#5','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'mc','auto','5107, 6714, 5400 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":5,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"5107, 6714, 5400 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"6714","correct":true},{"t":"5400","mis":"M2-2-u1-X13"},{"t":"5107","mis":"M2-2-u1-X15"}],"explanation":["천의 자리 숫자를 먼저 견주어요 — 5, 6, 5예요.","천의 자리 숫자가 가장 큰 6714가 가장 커요.","나머지 두 수는 백의 자리로 견주면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#6','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'mc','auto','5107, 6714, 5400 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"5107, 6714, 5400 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"5107","correct":true},{"t":"5400","mis":"M2-2-u1-X13"},{"t":"6714","mis":"M2-2-u1-X15"}],"explanation":["천의 자리가 5인 5107과 5400을 견주어요.","백의 자리 숫자 1이 4보다 작아서 5107이 가장 작아요.","묻는 말이 「가장 작은」인지 꼭 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#7','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'blank','auto','2180은 1422보다 (        ).',ARRAY['M2-2-u1-X14','M2-2-u1-X13']::text[],false,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":2,"kind":"blank","stem":"2180은 1422보다 (        ).","options":[{"t":"큽니다","correct":true},{"t":"작습니다","mis":"M2-2-u1-X14"},{"t":"같습니다","mis":"M2-2-u1-X13"}],"explanation":["천의 자리 숫자 2가 1보다 커요.","그래서 2180은 1422보다 큽니다 — 2180 > 1422.","같은 상황을 「1422는 2180보다 작습니다」로도 말할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#8','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'mc','auto','수 카드 놀이를 했어요. 나는 3725, 짝은 3752를 만들었어요. 1점을 얻는 사람은 누구인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":8,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"수 카드 놀이를 했어요. 나는 3725, 짝은 3752를 만들었어요. 1점을 얻는 사람은 누구인가요?","options":[{"t":"짝","correct":true},{"t":"나","mis":"M2-2-u1-X13"},{"t":"비겨요","mis":"M2-2-u1-X13"}],"explanation":["천의 자리 3, 백의 자리 7은 같아요.","십의 자리 숫자 5가 2보다 커서 짝의 3752가 더 커요.","그래서 더 큰 수를 만든 짝이 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#9','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'ox','auto','천의 자리 수가 같으면 백의 자리 수를 비교해요.',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":9,"concept":"M2-2-u1-C6","difficulty":2,"kind":"ox","stem":"천의 자리 수가 같으면 백의 자리 수를 비교해요.","answer":"O","reason_options":[{"t":"높은 자리부터 차례로 견주니까","correct":true},{"t":"일의 자리부터 견주어야 하니까","mis":"M2-2-u1-X13"}],"mis":"M2-2-u1-X13","explanation":["네 자리 수는 천의 자리부터 견주어요.","천의 자리 수가 같으면 그다음 높은 백의 자리를 견주어요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_basic#10','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',3,'sa','auto','1부터 9까지의 수 가운데 □ 안에 들어갈 수 있는 수를 찾아요. 4518 < □618 에서 □에 들어갈 수 있는 가장 작은 수는 무엇인가요?','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C6","difficulty":3,"kind":"sa","stem":"1부터 9까지의 수 가운데 □ 안에 들어갈 수 있는 수를 찾아요. 4518 < □618 에서 □에 들어갈 수 있는 가장 작은 수는 무엇인가요?","answer":["4"],"explanation":["□에 3을 넣으면 3618 — 4518보다 작아요.","□에 4를 넣으면 4618 — 천의 자리는 같고 백의 자리 6이 5보다 커서 4518보다 커요.","그래서 가장 작은 수는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#1','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',2,'error','auto','친구들이 1422와 2046을 비교했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X14']::text[],false,'{"seq":1,"concept":"M2-2-u1-C6","difficulty":2,"kind":"error","stem":"친구들이 1422와 2046을 비교했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우: 1422에는 4가 있으니 2046보다 커.","correct":true,"mis_target":"M2-2-u1-X13"},{"t":"하린: 2046이 1422보다 커.","mis":"M2-2-u1-X14"},{"t":"도윤: 천의 자리부터 견줘야 해.","mis":"M2-2-u1-X13"}],"explanation":["천의 자리 숫자를 먼저 견주면 1과 2예요.","천의 자리 숫자가 큰 2046이 더 커요.","뒤쪽 숫자에 속은 은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#2','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',2,'sa','auto','1부터 9까지의 수 가운데 4518 < □618 의 □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u1-C6","difficulty":2,"kind":"sa","stem":"1부터 9까지의 수 가운데 4518 < □618 의 □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["6","6개"],"explanation":["□가 4이면 4618 — 백의 자리를 견주어 4518보다 커요.","□가 4, 5, 6, 7, 8, 9이면 모두 커요.","그래서 모두 6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#3','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','1부터 9까지의 수 가운데 6419 < □518 의 □ 안에 들어갈 수 있는 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":3,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"1부터 9까지의 수 가운데 6419 < □518 의 □ 안에 들어갈 수 있는 가장 작은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u1-X13"},{"t":"5","mis":"M2-2-u1-X13"}],"explanation":["□에 6을 넣으면 6518 — 천의 자리는 같고 백의 자리 5가 4보다 커요.","그래서 6518은 6419보다 커요.","□가 6일 때도 꼭 확인해요 — 가장 작은 수는 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#4','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','7869, 7769, 7896 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":4,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"7869, 7769, 7896 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"7896","correct":true},{"t":"7869","mis":"M2-2-u1-X13"},{"t":"7769","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 모두 7이에요.","백의 자리 8인 7869와 7896을 십의 자리로 견주면 9가 6보다 커요.","그래서 7896이 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#5','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','수 카드 놀이를 해요. 나는 4, 9, 1, 6을, 짝은 7, 2, 8, 3을 뒤집었어요. 둘 다 가장 큰 네 자리 수를 만들면 1점을 얻는 사람은 누구인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X16']::text[],false,'{"seq":5,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 놀이를 해요. 나는 4, 9, 1, 6을, 짝은 7, 2, 8, 3을 뒤집었어요. 둘 다 가장 큰 네 자리 수를 만들면 1점을 얻는 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"짝","mis":"M2-2-u1-X13"},{"t":"비겨요","mis":"M2-2-u1-X16"}],"explanation":["나는 9641, 짝은 8732를 만들 수 있어요.","천의 자리 숫자 9가 8보다 커요.","그래서 내가 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#6','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'ox','auto','독도 이야기에 나온 1982, 1999, 2005, 2010 가운데 가장 오래전의 연도는 2010년이에요.',ARRAY['M2-2-u1-X15']::text[],false,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":3,"kind":"ox","stem":"독도 이야기에 나온 1982, 1999, 2005, 2010 가운데 가장 오래전의 연도는 2010년이에요.","answer":"X","reason_options":[{"t":"연도는 수가 작을수록 오래전이니 1982년이 가장 오래전이니까","correct":true},{"t":"수가 클수록 오래전이니까","mis":"M2-2-u1-X15"}],"mis":"M2-2-u1-X15","explanation":["네 수 가운데 가장 작은 수는 1982예요.","연도는 수가 작을수록 더 오래전에 일어난 일이에요.","그래서 틀린 말이에요 — 2010년은 가장 최근이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#7','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','5400 ○ 5107 — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M2-2-u1-X14','M2-2-u1-X13']::text[],false,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"5400 ○ 5107 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리 숫자는 5로 같아요.","백의 자리 숫자 4가 1보다 커서 5400이 더 커요.","그래서 5400 > 5107이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#8','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'sa','auto','0부터 9까지의 수 가운데 5□07 > 5400 의 □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?','{}'::text[],false,'{"seq":8,"concept":"M2-2-u1-C6","difficulty":4,"kind":"sa","stem":"0부터 9까지의 수 가운데 5□07 > 5400 의 □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["6","6개"],"explanation":["□가 4이면 5407 — 일의 자리 7이 0보다 커서 5400보다 커요.","□가 3 이하이면 5400보다 작아요. □는 4, 5, 6, 7, 8, 9예요.","그래서 모두 6개예요 — □가 같을 때도 꼭 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#9','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'mc','auto','수 카드 놀이를 「더 작은 수를 만든 사람이 1점」으로 바꾸었어요. 나는 3, 8, 1, 5를, 짝은 2, 9, 4, 7을 뒤집었어요. 둘 다 가장 작은 네 자리 수를 만들면 1점을 얻는 사람은 누구인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],false,'{"seq":9,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 놀이를 「더 작은 수를 만든 사람이 1점」으로 바꾸었어요. 나는 3, 8, 1, 5를, 짝은 2, 9, 4, 7을 뒤집었어요. 둘 다 가장 작은 네 자리 수를 만들면 1점을 얻는 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"짝","mis":"M2-2-u1-X15"},{"t":"비겨요","mis":"M2-2-u1-X16"}],"explanation":["나는 1358, 짝은 2479를 만들 수 있어요.","천의 자리 숫자 1이 2보다 작아요.","더 작은 수를 만든 내가 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_L07_challenge#10','math',2,2,'u1','L07','tb_g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'essay','teacher','1422와 2180의 크기를 비교하는 방법을 자리 이름을 넣어 설명하고, 천의 자리 수가 같은 5107과 5400은 어떻게 비교하는지도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C6","difficulty":4,"kind":"essay","stem":"1422와 2180의 크기를 비교하는 방법을 자리 이름을 넣어 설명하고, 천의 자리 수가 같은 5107과 5400은 어떻게 비교하는지도 써 보세요.","answer_guide":{"answer":"천의 자리부터 비교한다. 1422의 천의 자리 1이 2180의 천의 자리 2보다 작으므로 1422 < 2180. 5107과 5400은 천의 자리가 같으므로 백의 자리를 비교하여 1 < 4, 5107 < 5400.","scoring_points":["천의 자리부터 비교한다고 썼는가","천의 자리가 같으면 다음 백의 자리를 비교한다고 썼는가","두 경우 모두 부등호를 바르게 썼는가"]},"explanation":["수의 크기는 높은 자리부터 견주어요.","천의 자리 수가 다르면 거기서 바로 정해져요.","같으면 백, 십, 일의 자리 차례로 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#1','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',1,'mc','auto','연을 천 모형으로 나타냈어요. 수를 바르게 쓰고 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07']::text[],false,'{"seq":1,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"연을 천 모형으로 나타냈어요. 수를 바르게 쓰고 읽은 것은 어느 것인가요?","options":[{"t":"3000 — 삼천","correct":true},{"t":"300 — 삼백","mis":"M2-2-u1-X03"},{"t":"3000 — 삼영영영","mis":"M2-2-u1-X07"}],"explanation":["천 모형 하나는 1000이에요.","천 모형 3개는 1000이 3개 — 3000, 「삼천」이에요.","천 모형과 백 모형을 헷갈리지 않아요."],"asset":{"type":"blocks4","th":3,"h":0,"t":0,"o":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#2','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X06']::text[],false,'{"seq":2,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"4352","correct":true},{"t":"4000300502","mis":"M2-2-u1-X05"},{"t":"4325","mis":"M2-2-u1-X06"}],"explanation":["천 모형 4개, 백 모형 3개, 십 모형 5개, 일 모형 2개예요.","천·백·십·일의 자리에 4, 3, 5, 2 — 4352예요.","4352 = 4000 + 300 + 50 + 2예요."],"asset":{"type":"blocks4","th":4,"h":3,"t":5,"o":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#3','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',1,'mc','auto','5708을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X04']::text[],false,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"5708을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"오천칠백팔","correct":true},{"t":"오천칠백영십팔","mis":"M2-2-u1-X07"},{"t":"오천칠백팔십","mis":"M2-2-u1-X04"}],"explanation":["높은 자리부터 숫자 뒤에 자리 이름을 붙여 읽어요.","5708은 「오천칠백팔」이라고 읽어요.","0인 자리는 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#4','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',1,'mc','auto','1596에서 천의 자리 숫자 1이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":4,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"1596에서 천의 자리 숫자 1이 나타내는 값은 얼마인가요?","options":[{"t":"1000","correct":true},{"t":"1","mis":"M2-2-u1-X09"},{"t":"100","mis":"M2-2-u1-X08"}],"explanation":["1596에서 1은 천의 자리 숫자예요.","천의 자리 숫자 1은 1000을 나타내요.","숫자가 놓인 자리를 보고 값을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#5','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',1,'sa','auto','세미의 독도 지킴이 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 계속 저금하면 10월에는 얼마가 되나요?','{}'::text[],false,'{"seq":5,"concept":"M2-2-u1-C5","difficulty":1,"kind":"sa","stem":"세미의 독도 지킴이 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 계속 저금하면 10월에는 얼마가 되나요?","answer":["3360","3360원"],"explanation":["한 달에 1000원씩 늘어나니 1000씩 뛰어 세요.","9월 2360원에서 1번 뛰면 3360원이에요.","1000씩 뛰면 천의 자리 숫자만 1씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#6','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',1,'mc','auto','1422 ○ 2180 — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M2-2-u1-X14','M2-2-u1-X13']::text[],false,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"1422 ○ 2180 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리부터 차례로 견주어요.","천의 자리에서 처음 달라요 — 1은 2보다 작아요.","그래서 1422 < 2180예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#7','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C1',1,'sa','auto','999보다 1만큼 더 큰 수는 얼마인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u1-C1","difficulty":1,"kind":"sa","stem":"999보다 1만큼 더 큰 수는 얼마인가요?","answer":["1000"],"explanation":["999 바로 다음 수예요.","999보다 1 큰 수는 1000이에요.","9 뒤에 10을 붙이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#8','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',1,'mc','auto','태극기는 1개에 1000원이에요. 태극기 4개를 사려면 얼마를 내야 하나요?',ARRAY['M2-2-u1-X03']::text[],false,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"태극기는 1개에 1000원이에요. 태극기 4개를 사려면 얼마를 내야 하나요?","options":[{"t":"4000원","correct":true},{"t":"400원","mis":"M2-2-u1-X03"},{"t":"1004원","mis":"M2-2-u1-X03"}],"explanation":["1000원씩 4번 세어요.","1000이 4개이면 4000 — 4000원이에요.","4000은 「사천」이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#9','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',2,'mc','auto','5591을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":9,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"5591을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5000 + 500 + 90 + 1","correct":true},{"t":"5 + 5 + 9 + 1","mis":"M2-2-u1-X09"},{"t":"5000 + 50 + 90 + 1","mis":"M2-2-u1-X08"}],"explanation":["5591은 1000이 5개, 100이 5개, 10이 9개, 1이 1개예요.","그래서 5591 = 5000 + 500 + 90 + 1예요.","숫자만 더하면 안 돼요 — 자리마다 나타내는 값을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#10','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',2,'mc','auto','자릿값 카드 찾기 놀이를 해요. 선생님이 2595에서 백의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":10,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"자릿값 카드 찾기 놀이를 해요. 선생님이 2595에서 백의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?","options":[{"t":"500","correct":true},{"t":"5","mis":"M2-2-u1-X09"},{"t":"5000","mis":"M2-2-u1-X08"}],"explanation":["2595에서 백의 자리 숫자는 5예요.","백의 자리 숫자 5는 500을 나타내요.","그래서 500이 적힌 카드를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#11','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',2,'mc','auto','1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],false,'{"seq":11,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"4167","correct":true},{"t":"3168","mis":"M2-2-u1-X11"},{"t":"3267","mis":"M2-2-u1-X11"}],"explanation":["1000씩 뛰면 천의 자리 숫자가 1씩 커져요.","빈칸에는 4167이 들어가요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[2167,3167,null,5167],"step":1000}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#12','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',2,'sa','auto','1000이 2개, 100이 0개, 10이 5개, 1이 1개인 수는 얼마인가요?','{}'::text[],false,'{"seq":12,"concept":"M2-2-u1-C3","difficulty":2,"kind":"sa","stem":"1000이 2개, 100이 0개, 10이 5개, 1이 1개인 수는 얼마인가요?","answer":["2051"],"explanation":["개수를 천의 자리부터 차례로 써요 — 2, 0, 5, 1.","그래서 2051이에요.","개수가 0인 자리에는 0을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#13','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',2,'mc','auto','5107, 6714, 5400 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":13,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"5107, 6714, 5400 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"6714","correct":true},{"t":"5400","mis":"M2-2-u1-X13"},{"t":"5107","mis":"M2-2-u1-X15"}],"explanation":["천의 자리부터 차례로 견주어요.","가장 큰 수는 6714예요.","천의 자리가 같으면 백의 자리를 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#14','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C7',2,'sa','auto','3000을 1000과 100을 모두 써서 나타내요. 1000을 2개 쓰면 100은 몇 개를 써야 하나요?','{}'::text[],false,'{"seq":14,"concept":"M2-2-u1-C7","difficulty":2,"kind":"sa","stem":"3000을 1000과 100을 모두 써서 나타내요. 1000을 2개 쓰면 100은 몇 개를 써야 하나요?","answer":["10","10개"],"explanation":["1000이 2개는 2000이에요.","나머지 1000은 100이 10개예요.","그래서 100을 10개 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#15','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',2,'mc','auto','손수건이 1536장 있어요. 물건의 수를 세어 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u1-X17']::text[],false,'{"seq":15,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"손수건이 1536장 있어요. 물건의 수를 세어 바르게 말한 것은 어느 것인가요?","options":[{"t":"천오백서른여섯 장","correct":true},{"t":"천오백삼십육 장","mis":"M2-2-u1-X17"},{"t":"천오백셋십여섯 장","mis":"M2-2-u1-X17"}],"explanation":["수 1536은 「천오백삼십육」이라고 읽어요.","물건을 셀 때는 「천오백서른여섯 장」이라고 말해요.","읽는 말과 세는 말을 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#16','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',2,'mc','auto','독도 이야기책의 네 사건(1982년 · 1999년 · 2005년 · 2010년)을 일어난 순서대로 놓아요. 가장 먼저 일어난 일은 어느 것인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X13']::text[],false,'{"seq":16,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"독도 이야기책의 네 사건(1982년 · 1999년 · 2005년 · 2010년)을 일어난 순서대로 놓아요. 가장 먼저 일어난 일은 어느 것인가요?","options":[{"t":"1982년 — 독도를 천연기념물로 정했어요","correct":true},{"t":"2010년 — 독도를 여행한 사람들에게 명예 주민증을 만들어 주기 시작했어요","mis":"M2-2-u1-X15"},{"t":"1999년 — 독도 천연 보호 구역으로 이름을 바꾸어 보호하기 시작했어요","mis":"M2-2-u1-X13"}],"explanation":["연도는 수가 작을수록 오래전, 클수록 최근이에요.","천의 자리부터 견주면 1982 < 1999 < 2005 < 2010이에요.","그래서 가장 먼저 일어난 일은 1982년이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#17','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',3,'mc','auto','수 카드 0, 2, 5, 7을 한 번씩만 써서 네 자리 수를 만들어요. 백의 자리 숫자가 700을 나타내는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X16']::text[],false,'{"seq":17,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"수 카드 0, 2, 5, 7을 한 번씩만 써서 네 자리 수를 만들어요. 백의 자리 숫자가 700을 나타내는 수는 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"6개","mis":"M2-2-u1-X16"},{"t":"3개","mis":"M2-2-u1-X16"}],"explanation":["백의 자리에 7을 놓고, 0은 천의 자리에 오지 않게 해요.","2705, 2750, 5702, 5720 — 모두 4개예요.","0이 천의 자리에 오면 네 자리 수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#18','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',3,'mc','auto','1부터 9까지의 수 가운데 6419 < □518 의 □ 안에 들어갈 수 있는 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"1부터 9까지의 수 가운데 6419 < □518 의 □ 안에 들어갈 수 있는 가장 작은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u1-X13"},{"t":"5","mis":"M2-2-u1-X13"}],"explanation":["□에 6을 넣으면 6518 — 천의 자리가 같으니 백의 자리를 견주어요.","백의 자리 5가 4보다 커서 6419보다 커요.","그래서 가장 작은 수는 6이에요 — 같은 천의 자리도 꼭 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#19','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',3,'mc','auto','9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":19,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"9924","correct":true},{"t":"9933","mis":"M2-2-u1-X12"},{"t":"9915","mis":"M2-2-u1-X12"}],"explanation":["오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요.","빈칸 둘레의 수에서 오른쪽은 1씩, 아래는 10씩 세어 보면 9924예요.","두 방향으로 확인하면 틀리지 않아요."],"asset":{"type":"numgrid","rows":[[9901,9902,9903,9904],[9911,9912,9913,9914],[9921,9922,9923,null]],"name":"수 배열표","q":[2,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#20','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C7',3,'mc','auto','지아는 3800원을 내고 딸기우유(1700원)와 바나나우유를 한 개씩 샀어요. 낸 돈에서 딸기우유 값만큼 묶고 남은 돈이 바나나우유 값이에요. 바나나우유는 얼마인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],false,'{"seq":20,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"지아는 3800원을 내고 딸기우유(1700원)와 바나나우유를 한 개씩 샀어요. 낸 돈에서 딸기우유 값만큼 묶고 남은 돈이 바나나우유 값이에요. 바나나우유는 얼마인가요?","options":[{"t":"2100원","correct":true},{"t":"3800원","mis":"M2-2-u1-X15"},{"t":"1100원","mis":"M2-2-u1-X12"}],"explanation":["3800원은 천 원짜리 3장과 100원짜리 8개예요.","1700원(천 원짜리 1장, 100원짜리 7개)을 묶으면 천 원짜리 2장, 100원짜리 1개가 남아요.","그래서 바나나우유는 2100원이에요."],"asset":{"type":"blocks4","th":3,"h":8,"t":0,"o":0,"unit":"coin"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#21','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',3,'mc','auto','친구의 생일 선물을 5000원만큼 사려고 해요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],false,'{"seq":21,"concept":"M2-2-u1-C2","difficulty":3,"kind":"mc","stem":"친구의 생일 선물을 5000원만큼 사려고 해요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?","options":[{"t":"사인펜과 지우개","correct":true},{"t":"색연필과 필통","mis":"M2-2-u1-X15"},{"t":"연필과 고무찰흙","mis":"M2-2-u1-X12"}],"explanation":["사인펜 4000원과 지우개 1000원 — 1000원이 4장과 1장이에요.","1000원이 모두 5장 — 5000원이에요.","색연필과 필통은 7000원, 연필과 고무찰흙은 4000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#22','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',3,'error','auto','친구들이 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04','M2-2-u1-X06']::text[],false,'{"seq":22,"concept":"M2-2-u1-C3","difficulty":3,"kind":"error","stem":"친구들이 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"민호: 사천삼백오십이 → 4000300502","correct":true,"mis_target":"M2-2-u1-X05"},{"t":"하린: 이천오십일 → 2051","mis":"M2-2-u1-X04"},{"t":"도윤: 삼천이백오십팔 → 3258","mis":"M2-2-u1-X06"}],"explanation":["사천삼백오십이는 4352예요.","각 자리 값을 그대로 이어 쓰면 안 돼요.","그래서 민호가 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#23','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',4,'mc','auto','수 카드 놀이를 해요. 나는 4, 9, 1, 6을, 짝은 7, 2, 8, 3을 뒤집었어요. 둘 다 가장 큰 네 자리 수를 만들고 더 큰 수를 만든 사람이 1점을 얻어요. 1점을 얻는 사람은 누구인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],false,'{"seq":23,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 놀이를 해요. 나는 4, 9, 1, 6을, 짝은 7, 2, 8, 3을 뒤집었어요. 둘 다 가장 큰 네 자리 수를 만들고 더 큰 수를 만든 사람이 1점을 얻어요. 1점을 얻는 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"짝","mis":"M2-2-u1-X15"},{"t":"비겨요","mis":"M2-2-u1-X16"}],"explanation":["나는 9641, 짝은 8732를 만들 수 있어요.","천의 자리부터 견주면 9641 > 8732예요.","그래서 나가 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#24','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',4,'mc','auto','세미의 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 저금하면 처음으로 3000원보다 많아지는 달은 언제인가요?',ARRAY['M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"세미의 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 저금하면 처음으로 3000원보다 많아지는 달은 언제인가요?","options":[{"t":"10월","correct":true},{"t":"11월","mis":"M2-2-u1-X15"},{"t":"12월","mis":"M2-2-u1-X15"}],"explanation":["9월 2360원, 10월 3360원, 11월 4360원, 12월 5360원 — 1000씩 뛰어 세요.","3000원보다 처음 많아지는 것은 3360원인 10월이에요.","「처음으로 많아지는」 달을 묻는 것인지 꼭 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_a#25','math',2,2,'u1','','tb_g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',4,'essay','teacher','독도 이야기책의 연도 2010, 1982, 2005, 1999를 일어난 순서대로 쓰고, 어떻게 순서를 정했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C6","difficulty":4,"kind":"essay","stem":"독도 이야기책의 연도 2010, 1982, 2005, 1999를 일어난 순서대로 쓰고, 어떻게 순서를 정했는지 설명해 보세요.","answer_guide":{"answer":"1982, 1999, 2005, 2010. 천의 자리부터 비교하여 1인 1982와 1999가 먼저이고, 천의 자리가 같으면 백의 자리를 비교한다(9와 9가 같으면 십의 자리 8 < 9). 연도는 수가 작을수록 오래전이다.","scoring_points":["네 연도를 순서대로 바르게 썼는가","천의 자리부터, 같으면 다음 자리를 비교했다고 썼는가","연도는 작을수록 오래전이라는 것을 썼는가"]},"explanation":["연도도 네 자리 수라 크기를 비교할 수 있어요.","천의 자리가 같은 1982와 1999는 십의 자리에서 갈려요.","작은 수부터 놓으면 일어난 순서가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#1','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',1,'mc','auto','연을 천 모형으로 나타냈어요. 수를 바르게 쓰고 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07']::text[],false,'{"seq":1,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"연을 천 모형으로 나타냈어요. 수를 바르게 쓰고 읽은 것은 어느 것인가요?","options":[{"t":"5000 — 오천","correct":true},{"t":"500 — 오백","mis":"M2-2-u1-X03"},{"t":"5000 — 오영영영","mis":"M2-2-u1-X07"}],"explanation":["천 모형 하나는 1000이에요.","천 모형 5개는 1000이 5개 — 5000, 「오천」이에요.","천 모형과 백 모형을 헷갈리지 않아요."],"asset":{"type":"blocks4","th":5,"h":0,"t":0,"o":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#2','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X06']::text[],false,'{"seq":2,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3258","correct":true},{"t":"3000200508","mis":"M2-2-u1-X05"},{"t":"3285","mis":"M2-2-u1-X06"}],"explanation":["천 모형 3개, 백 모형 2개, 십 모형 5개, 일 모형 8개예요.","천·백·십·일의 자리에 3, 2, 5, 8 — 3258이에요.","3258 = 3000 + 200 + 50 + 8예요."],"asset":{"type":"blocks4","th":3,"h":2,"t":5,"o":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#3','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',1,'mc','auto','2051을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X04']::text[],false,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"2051을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"이천오십일","correct":true},{"t":"이천영백오십일","mis":"M2-2-u1-X07"},{"t":"이천오백일","mis":"M2-2-u1-X04"}],"explanation":["높은 자리부터 숫자 뒤에 자리 이름을 붙여 읽어요.","2051은 「이천오십일」이라고 읽어요.","0인 자리는 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#4','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',1,'mc','auto','1408에서 백의 자리 숫자 4가 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":4,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"1408에서 백의 자리 숫자 4가 나타내는 값은 얼마인가요?","options":[{"t":"400","correct":true},{"t":"4","mis":"M2-2-u1-X09"},{"t":"4000","mis":"M2-2-u1-X08"}],"explanation":["1408에서 4는 백의 자리 숫자예요.","백의 자리 숫자 4는 400을 나타내요.","숫자가 놓인 자리를 보고 값을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#5','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',1,'sa','auto','세미의 독도 지킴이 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 계속 저금하면 11월에는 얼마가 되나요?','{}'::text[],false,'{"seq":5,"concept":"M2-2-u1-C5","difficulty":1,"kind":"sa","stem":"세미의 독도 지킴이 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 계속 저금하면 11월에는 얼마가 되나요?","answer":["4360","4360원"],"explanation":["한 달에 1000원씩 늘어나니 1000씩 뛰어 세요.","9월 2360원에서 2번 뛰면 4360원이에요.","1000씩 뛰면 천의 자리 숫자만 1씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#6','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',1,'mc','auto','5400 ○ 5107 — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M2-2-u1-X14','M2-2-u1-X13']::text[],false,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"5400 ○ 5107 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리부터 차례로 견주어요.","백의 자리에서 처음 달라요 — 4는 1보다 커요.","그래서 5400 > 5107예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#7','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C1',1,'sa','auto','990보다 10만큼 더 큰 수는 얼마인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u1-C1","difficulty":1,"kind":"sa","stem":"990보다 10만큼 더 큰 수는 얼마인가요?","answer":["1000"],"explanation":["990에서 10을 더 뛰어요.","990보다 10 큰 수는 1000이에요.","수 배열표에서 오른쪽으로 한 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#8','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',1,'mc','auto','태극기는 1개에 1000원이에요. 태극기 6개를 사려면 얼마를 내야 하나요?',ARRAY['M2-2-u1-X03']::text[],false,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"태극기는 1개에 1000원이에요. 태극기 6개를 사려면 얼마를 내야 하나요?","options":[{"t":"6000원","correct":true},{"t":"600원","mis":"M2-2-u1-X03"},{"t":"1006원","mis":"M2-2-u1-X03"}],"explanation":["1000원씩 6번 세어요.","1000이 6개이면 6000 — 6000원이에요.","6000은 「육천」이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#9','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',2,'mc','auto','5836을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":9,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"5836을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5000 + 800 + 30 + 6","correct":true},{"t":"5 + 8 + 3 + 6","mis":"M2-2-u1-X09"},{"t":"5000 + 80 + 30 + 6","mis":"M2-2-u1-X08"}],"explanation":["5836은 1000이 5개, 100이 8개, 10이 3개, 1이 6개예요.","그래서 5836 = 5000 + 800 + 30 + 6예요.","숫자만 더하면 안 돼요 — 자리마다 나타내는 값을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#10','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',2,'mc','auto','자릿값 카드 찾기 놀이를 해요. 선생님이 2595에서 천의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":10,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"자릿값 카드 찾기 놀이를 해요. 선생님이 2595에서 천의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?","options":[{"t":"2000","correct":true},{"t":"2","mis":"M2-2-u1-X09"},{"t":"200","mis":"M2-2-u1-X08"}],"explanation":["2595에서 천의 자리 숫자는 2예요.","천의 자리 숫자 2는 2000을 나타내요.","그래서 2000이 적힌 카드를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#11','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',2,'mc','auto','100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11','M2-2-u1-X12']::text[],false,'{"seq":11,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"7669","correct":true},{"t":"7759","mis":"M2-2-u1-X11"},{"t":"7869","mis":"M2-2-u1-X12"}],"explanation":["100씩 거꾸로 뛰면 백의 자리 숫자가 1씩 작아져요.","빈칸에는 7669가 들어가요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[7869,7769,null,7569],"step":100,"dir":"down"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#12','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',2,'sa','auto','1000이 5개, 100이 7개, 10이 0개, 1이 8개인 수는 얼마인가요?','{}'::text[],false,'{"seq":12,"concept":"M2-2-u1-C3","difficulty":2,"kind":"sa","stem":"1000이 5개, 100이 7개, 10이 0개, 1이 8개인 수는 얼마인가요?","answer":["5708"],"explanation":["개수를 천의 자리부터 차례로 써요 — 5, 7, 0, 8.","그래서 5708이에요.","개수가 0인 자리에는 0을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#13','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',2,'mc','auto','5107, 6714, 5400 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":13,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"5107, 6714, 5400 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"5107","correct":true},{"t":"5400","mis":"M2-2-u1-X13"},{"t":"6714","mis":"M2-2-u1-X15"}],"explanation":["천의 자리부터 차례로 견주어요.","가장 작은 수는 5107이에요.","천의 자리가 같으면 백의 자리를 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#14','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C7',2,'sa','auto','5000원을 천 원짜리 3장과 100원짜리 동전으로 꼭 맞게 내려면 100원짜리는 몇 개가 있어야 하나요?','{}'::text[],false,'{"seq":14,"concept":"M2-2-u1-C7","difficulty":2,"kind":"sa","stem":"5000원을 천 원짜리 3장과 100원짜리 동전으로 꼭 맞게 내려면 100원짜리는 몇 개가 있어야 하나요?","answer":["20","20개"],"explanation":["천 원짜리 3장은 3000원이에요.","나머지 2000원은 100원짜리 20개예요.","100이 10개면 1000이니 20개면 2000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#15','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',2,'mc','auto','3월에 독도에 간 사람이 5591명이에요. 사람의 수를 세어 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u1-X17']::text[],false,'{"seq":15,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"3월에 독도에 간 사람이 5591명이에요. 사람의 수를 세어 바르게 말한 것은 어느 것인가요?","options":[{"t":"오천오백아흔한 명","correct":true},{"t":"오천오백구십일 명","mis":"M2-2-u1-X17"},{"t":"오천다섯백아흔한 명","mis":"M2-2-u1-X17"}],"explanation":["수 5591은 「오천오백구십일」이라고 읽어요.","사람을 셀 때는 「오천오백아흔한 명」이라고 말해요.","읽는 말과 세는 말을 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#16','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',2,'mc','auto','독도 이야기책의 네 사건(1982년 · 1999년 · 2005년 · 2010년)을 일어난 순서대로 놓아요. 가장 최근에 일어난 일은 어느 것인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X13']::text[],false,'{"seq":16,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"독도 이야기책의 네 사건(1982년 · 1999년 · 2005년 · 2010년)을 일어난 순서대로 놓아요. 가장 최근에 일어난 일은 어느 것인가요?","options":[{"t":"2010년 — 독도를 여행한 사람들에게 명예 주민증을 만들어 주기 시작했어요","correct":true},{"t":"1982년 — 독도를 천연기념물로 정했어요","mis":"M2-2-u1-X15"},{"t":"2005년 — 독도를 여행할 수 있게 되었어요","mis":"M2-2-u1-X13"}],"explanation":["연도는 수가 작을수록 오래전, 클수록 최근이에요.","천의 자리부터 견주면 1982 < 1999 < 2005 < 2010이에요.","그래서 가장 최근에 일어난 일은 2010년이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#17','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',3,'mc','auto','수 카드 0, 2, 5, 7을 한 번씩만 써서 네 자리 수를 만들어요. 백의 자리 숫자가 700을 나타내는 수 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X16']::text[],false,'{"seq":17,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"수 카드 0, 2, 5, 7을 한 번씩만 써서 네 자리 수를 만들어요. 백의 자리 숫자가 700을 나타내는 수 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"5720","correct":true},{"t":"7520","mis":"M2-2-u1-X08"},{"t":"5702","mis":"M2-2-u1-X16"}],"explanation":["백의 자리는 7로 정해져 있어요.","천의 자리에 5, 십의 자리에 2, 일의 자리에 0 — 5720이에요.","7520은 7이 천의 자리라서 7000을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#18','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',3,'mc','auto','1부터 9까지의 수 가운데 4518 < □618 의 □ 안에 들어갈 수 있는 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"1부터 9까지의 수 가운데 4518 < □618 의 □ 안에 들어갈 수 있는 가장 작은 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u1-X13"},{"t":"3","mis":"M2-2-u1-X13"}],"explanation":["□에 4를 넣으면 4618 — 천의 자리가 같으니 백의 자리를 견주어요.","백의 자리 6이 5보다 커서 4518보다 커요.","그래서 가장 작은 수는 4예요 — 같은 천의 자리도 꼭 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#19','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',3,'mc','auto','9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":19,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"9953","correct":true},{"t":"9962","mis":"M2-2-u1-X12"},{"t":"9944","mis":"M2-2-u1-X12"}],"explanation":["오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요.","빈칸 둘레의 수에서 오른쪽은 1씩, 아래는 10씩 세어 보면 9953이에요.","두 방향으로 확인하면 틀리지 않아요."],"asset":{"type":"numgrid","rows":[[9942,9943,9944,9945],[9952,null,9954,9955],[9962,9963,9964,9965]],"name":"수 배열표","q":[1,1]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#20','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C7',3,'mc','auto','지아는 3800원을 내고 바나나우유(2100원)와 딸기우유를 한 개씩 샀어요. 낸 돈에서 바나나우유 값만큼 묶고 남은 돈이 딸기우유 값이에요. 딸기우유는 얼마인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],false,'{"seq":20,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"지아는 3800원을 내고 바나나우유(2100원)와 딸기우유를 한 개씩 샀어요. 낸 돈에서 바나나우유 값만큼 묶고 남은 돈이 딸기우유 값이에요. 딸기우유는 얼마인가요?","options":[{"t":"1700원","correct":true},{"t":"3800원","mis":"M2-2-u1-X15"},{"t":"1800원","mis":"M2-2-u1-X12"}],"explanation":["3800원은 천 원짜리 3장과 100원짜리 8개예요.","2100원(천 원짜리 2장, 100원짜리 1개)을 묶으면 천 원짜리 1장, 100원짜리 7개가 남아요.","그래서 딸기우유는 1700원이에요."],"asset":{"type":"blocks4","th":3,"h":8,"t":0,"o":0,"unit":"coin"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#21','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',3,'mc','auto','친구의 생일 선물을 5000원만큼 사려고 해요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],false,'{"seq":21,"concept":"M2-2-u1-C2","difficulty":3,"kind":"mc","stem":"친구의 생일 선물을 5000원만큼 사려고 해요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?","options":[{"t":"색연필과 연필","correct":true},{"t":"사인펜과 필통","mis":"M2-2-u1-X15"},{"t":"공책과 지우개","mis":"M2-2-u1-X12"}],"explanation":["색연필 3000원과 연필 2000원 — 1000원이 3장과 2장이에요.","1000원이 모두 5장 — 5000원이에요.","사인펜과 필통은 8000원, 공책과 지우개는 2000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#22','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',3,'error','auto','친구들이 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X03']::text[],false,'{"seq":22,"concept":"M2-2-u1-C3","difficulty":3,"kind":"error","stem":"친구들이 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"서아: 천 모형 2개, 일 모형 4개 → 24","correct":true,"mis_target":"M2-2-u1-X04"},{"t":"준우: 천 모형 3개 → 3000","mis":"M2-2-u1-X03"},{"t":"라희: 1000이 5개, 1이 8개 → 5008","mis":"M2-2-u1-X04"}],"explanation":["천 모형 2개와 일 모형 4개는 2004예요.","백의 자리와 십의 자리에 0을 써야 해요.","그래서 서아가 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#23','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',4,'mc','auto','수 카드 놀이를 해요. 나는 3, 8, 1, 5를, 짝은 2, 9, 4, 7을 뒤집었어요. 둘 다 가장 작은 네 자리 수를 만들고 더 작은 수를 만든 사람이 1점을 얻어요. 1점을 얻는 사람은 누구인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],false,'{"seq":23,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 놀이를 해요. 나는 3, 8, 1, 5를, 짝은 2, 9, 4, 7을 뒤집었어요. 둘 다 가장 작은 네 자리 수를 만들고 더 작은 수를 만든 사람이 1점을 얻어요. 1점을 얻는 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"짝","mis":"M2-2-u1-X15"},{"t":"비겨요","mis":"M2-2-u1-X16"}],"explanation":["나는 1358, 짝은 2479를 만들 수 있어요.","천의 자리부터 견주면 1358 < 2479예요.","그래서 나가 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#24','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',4,'mc','auto','세미의 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 저금하면 처음으로 4000원보다 많아지는 달은 언제인가요?',ARRAY['M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"세미의 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 저금하면 처음으로 4000원보다 많아지는 달은 언제인가요?","options":[{"t":"11월","correct":true},{"t":"10월","mis":"M2-2-u1-X15"},{"t":"12월","mis":"M2-2-u1-X15"}],"explanation":["9월 2360원, 10월 3360원, 11월 4360원, 12월 5360원 — 1000씩 뛰어 세요.","4000원보다 처음 많아지는 것은 4360원인 11월이에요.","「처음으로 많아지는」 달을 묻는 것인지 꼭 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_b#25','math',2,2,'u1','','tb_g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',4,'essay','teacher','친구가 「1422에는 4가 있으니까 2046보다 커요.」라고 말했어요. 친구의 생각이 맞는지 쓰고, 까닭을 자리 이름을 넣어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C6","difficulty":4,"kind":"essay","stem":"친구가 「1422에는 4가 있으니까 2046보다 커요.」라고 말했어요. 친구의 생각이 맞는지 쓰고, 까닭을 자리 이름을 넣어 설명해 보세요.","answer_guide":{"answer":"틀렸다. 네 자리 수는 천의 자리부터 비교한다. 1422의 천의 자리 숫자 1은 2046의 천의 자리 숫자 2보다 작으므로 1422 < 2046이다.","scoring_points":["친구의 생각이 틀렸다고 판단했는가","천의 자리부터 비교한다고 썼는가","1422 < 2046으로 바르게 나타냈는가"]},"explanation":["뒤쪽 숫자가 크다고 큰 수가 아니에요.","천의 자리 숫자가 다르면 거기서 크기가 정해져요.","1 < 2라서 1422가 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#1','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',1,'mc','auto','연을 천 모형으로 나타냈어요. 수를 바르게 쓰고 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07']::text[],false,'{"seq":1,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"연을 천 모형으로 나타냈어요. 수를 바르게 쓰고 읽은 것은 어느 것인가요?","options":[{"t":"8000 — 팔천","correct":true},{"t":"800 — 팔백","mis":"M2-2-u1-X03"},{"t":"8000 — 팔영영영","mis":"M2-2-u1-X07"}],"explanation":["천 모형 하나는 1000이에요.","천 모형 8개는 1000이 8개 — 8000, 「팔천」이에요.","천 모형과 백 모형을 헷갈리지 않아요."],"asset":{"type":"blocks4","th":8,"h":0,"t":0,"o":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#2','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X06']::text[],false,'{"seq":2,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"4392","correct":true},{"t":"4000300902","mis":"M2-2-u1-X05"},{"t":"4329","mis":"M2-2-u1-X06"}],"explanation":["천 모형 4개, 백 모형 3개, 십 모형 9개, 일 모형 2개예요.","천·백·십·일의 자리에 4, 3, 9, 2 — 4392예요.","4392 = 4000 + 300 + 90 + 2예요."],"asset":{"type":"blocks4","th":4,"h":3,"t":9,"o":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#3','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',1,'mc','auto','3015를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X04']::text[],false,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"3015를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"삼천십오","correct":true},{"t":"삼천영백일십오","mis":"M2-2-u1-X07"},{"t":"삼천백오","mis":"M2-2-u1-X04"}],"explanation":["높은 자리부터 숫자 뒤에 자리 이름을 붙여 읽어요.","3015는 「삼천십오」라고 읽어요.","0인 자리는 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#4','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',1,'mc','auto','5732에서 십의 자리 숫자 3이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":4,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"5732에서 십의 자리 숫자 3이 나타내는 값은 얼마인가요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M2-2-u1-X09"},{"t":"3000","mis":"M2-2-u1-X08"}],"explanation":["5732에서 3은 십의 자리 숫자예요.","십의 자리 숫자 3은 30을 나타내요.","숫자가 놓인 자리를 보고 값을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#5','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',1,'sa','auto','세미의 독도 지킴이 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 계속 저금하면 12월에는 얼마가 되나요?','{}'::text[],false,'{"seq":5,"concept":"M2-2-u1-C5","difficulty":1,"kind":"sa","stem":"세미의 독도 지킴이 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 계속 저금하면 12월에는 얼마가 되나요?","answer":["5360","5360원"],"explanation":["한 달에 1000원씩 늘어나니 1000씩 뛰어 세요.","9월 2360원에서 3번 뛰면 5360원이에요.","1000씩 뛰면 천의 자리 숫자만 1씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#6','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',1,'mc','auto','6714 ○ 5400 — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M2-2-u1-X14','M2-2-u1-X13']::text[],false,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"6714 ○ 5400 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리부터 차례로 견주어요.","천의 자리에서 처음 달라요 — 6은 5보다 커요.","그래서 6714 > 5400예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#7','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C1',1,'sa','auto','900보다 100만큼 더 큰 수는 얼마인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u1-C1","difficulty":1,"kind":"sa","stem":"900보다 100만큼 더 큰 수는 얼마인가요?","answer":["1000"],"explanation":["900에서 100을 더 뛰어요.","900보다 100 큰 수는 1000이에요.","수 배열표에서 아래로 한 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#8','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',1,'mc','auto','태극기는 1개에 1000원이에요. 태극기 9개를 사려면 얼마를 내야 하나요?',ARRAY['M2-2-u1-X03']::text[],false,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"태극기는 1개에 1000원이에요. 태극기 9개를 사려면 얼마를 내야 하나요?","options":[{"t":"9000원","correct":true},{"t":"900원","mis":"M2-2-u1-X03"},{"t":"1009원","mis":"M2-2-u1-X03"}],"explanation":["1000원씩 9번 세어요.","1000이 9개이면 9000 — 9000원이에요.","9000은 「구천」이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#9','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',2,'mc','auto','1297을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":9,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"1297을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1000 + 200 + 90 + 7","correct":true},{"t":"1 + 2 + 9 + 7","mis":"M2-2-u1-X09"},{"t":"1000 + 20 + 90 + 7","mis":"M2-2-u1-X08"}],"explanation":["1297은 1000이 1개, 100이 2개, 10이 9개, 1이 7개예요.","그래서 1297 = 1000 + 200 + 90 + 7예요.","숫자만 더하면 안 돼요 — 자리마다 나타내는 값을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#10','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',2,'mc','auto','자릿값 카드 찾기 놀이를 해요. 선생님이 3819에서 천의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":10,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"자릿값 카드 찾기 놀이를 해요. 선생님이 3819에서 천의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?","options":[{"t":"3000","correct":true},{"t":"3","mis":"M2-2-u1-X09"},{"t":"300","mis":"M2-2-u1-X08"}],"explanation":["3819에서 천의 자리 숫자는 3이에요.","천의 자리 숫자 3은 3000을 나타내요.","그래서 3000이 적힌 카드를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#11','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',2,'mc','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11','M2-2-u1-X12']::text[],false,'{"seq":11,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"3417","correct":true},{"t":"3318","mis":"M2-2-u1-X11"},{"t":"4317","mis":"M2-2-u1-X12"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","빈칸에는 3417이 들어가요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[3217,3317,null,3517],"step":100}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#12','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',2,'sa','auto','1000이 3개, 100이 0개, 10이 1개, 1이 5개인 수는 얼마인가요?','{}'::text[],false,'{"seq":12,"concept":"M2-2-u1-C3","difficulty":2,"kind":"sa","stem":"1000이 3개, 100이 0개, 10이 1개, 1이 5개인 수는 얼마인가요?","answer":["3015"],"explanation":["개수를 천의 자리부터 차례로 써요 — 3, 0, 1, 5.","그래서 3015예요.","개수가 0인 자리에는 0을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#13','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',2,'mc','auto','1982, 1999, 2005 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":13,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"1982, 1999, 2005 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"2005","correct":true},{"t":"1999","mis":"M2-2-u1-X13"},{"t":"1982","mis":"M2-2-u1-X15"}],"explanation":["천의 자리부터 차례로 견주어요.","가장 큰 수는 2005예요.","천의 자리가 같으면 백의 자리를 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#14','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C7',2,'sa','auto','6000을 1000 4개와 100 몇 개로 나타내요. 100은 몇 개가 있어야 하나요?','{}'::text[],false,'{"seq":14,"concept":"M2-2-u1-C7","difficulty":2,"kind":"sa","stem":"6000을 1000 4개와 100 몇 개로 나타내요. 100은 몇 개가 있어야 하나요?","answer":["20","20개"],"explanation":["1000이 4개는 4000이에요.","나머지 2000은 100이 20개예요.","그래서 100을 20개 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#15','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',2,'mc','auto','독도로 가는 여객선에 425명이 탔어요. 사람의 수를 세어 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u1-X17']::text[],false,'{"seq":15,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"독도로 가는 여객선에 425명이 탔어요. 사람의 수를 세어 바르게 말한 것은 어느 것인가요?","options":[{"t":"사백스물다섯 명","correct":true},{"t":"사백이십오 명","mis":"M2-2-u1-X17"},{"t":"넷백스물다섯 명","mis":"M2-2-u1-X17"}],"explanation":["수 425는 「사백이십오」라고 읽어요.","사람을 셀 때는 「사백스물다섯 명」이라고 말해요.","읽는 말과 세는 말을 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#16','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',2,'mc','auto','독도 이야기책의 네 사건(1982년 · 1999년 · 2005년 · 2010년)을 일어난 순서대로 놓아요. 두 번째로 일어난 일은 어느 것인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":16,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"독도 이야기책의 네 사건(1982년 · 1999년 · 2005년 · 2010년)을 일어난 순서대로 놓아요. 두 번째로 일어난 일은 어느 것인가요?","options":[{"t":"1999년 — 독도 천연 보호 구역으로 이름을 바꾸어 보호하기 시작했어요","correct":true},{"t":"2005년 — 독도를 여행할 수 있게 되었어요","mis":"M2-2-u1-X13"},{"t":"1982년 — 독도를 천연기념물로 정했어요","mis":"M2-2-u1-X15"}],"explanation":["연도는 수가 작을수록 오래전, 클수록 최근이에요.","천의 자리부터 견주면 1982 < 1999 < 2005 < 2010이에요.","그래서 두 번째로 일어난 일은 1999년이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#17','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',3,'mc','auto','수 카드 0, 2, 5, 7을 한 번씩만 써서 네 자리 수를 만들어요. 백의 자리 숫자가 700을 나타내는 수 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X16']::text[],false,'{"seq":17,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"수 카드 0, 2, 5, 7을 한 번씩만 써서 네 자리 수를 만들어요. 백의 자리 숫자가 700을 나타내는 수 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"2705","correct":true},{"t":"0725","mis":"M2-2-u1-X16"},{"t":"2750","mis":"M2-2-u1-X16"}],"explanation":["백의 자리에 7을 놓아요.","천의 자리에는 0이 올 수 없으니 2, 그다음 0, 5 — 2705예요.","0725는 네 자리 수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#18','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',3,'mc','auto','1부터 9까지의 수 가운데 6419 < □518 의 □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"1부터 9까지의 수 가운데 6419 < □518 의 □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"M2-2-u1-X13"},{"t":"5개","mis":"M2-2-u1-X13"}],"explanation":["□에 6을 넣으면 6518 — 6419보다 커요.","□는 6, 7, 8, 9예요.","그래서 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#19','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',3,'mc','auto','9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":19,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"9985","correct":true},{"t":"9994","mis":"M2-2-u1-X12"},{"t":"9976","mis":"M2-2-u1-X12"}],"explanation":["오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요.","빈칸 둘레의 수에서 오른쪽은 1씩, 아래는 10씩 세어 보면 9985예요.","두 방향으로 확인하면 틀리지 않아요."],"asset":{"type":"numgrid","rows":[[9965,9966,9967,9968],[9975,9976,9977,9978],[null,9986,9987,9988]],"name":"수 배열표","q":[2,0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#20','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C7',3,'mc','auto','딸기우유는 1700원, 바나나우유는 2100원이에요. 두 개를 한 개씩 사려면 천 원짜리와 100원짜리로 얼마를 내야 하나요?',ARRAY['M2-2-u1-X10','M2-2-u1-X06']::text[],false,'{"seq":20,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"딸기우유는 1700원, 바나나우유는 2100원이에요. 두 개를 한 개씩 사려면 천 원짜리와 100원짜리로 얼마를 내야 하나요?","options":[{"t":"3800원","correct":true},{"t":"2800원","mis":"M2-2-u1-X10"},{"t":"3080원","mis":"M2-2-u1-X06"}],"explanation":["천 원짜리는 1장과 2장 — 모두 3장이에요.","100원짜리는 7개와 1개 — 모두 8개예요.","천 원짜리 3장, 100원짜리 8개는 3800원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#21','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',3,'mc','auto','친구의 생일 선물을 5000원만큼 사려고 해요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],false,'{"seq":21,"concept":"M2-2-u1-C2","difficulty":3,"kind":"mc","stem":"친구의 생일 선물을 5000원만큼 사려고 해요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?","options":[{"t":"필통과 공책","correct":true},{"t":"색연필과 사인펜","mis":"M2-2-u1-X15"},{"t":"연필과 지우개","mis":"M2-2-u1-X12"}],"explanation":["필통 4000원과 공책 1000원 — 1000원이 4장과 1장이에요.","1000원이 모두 5장 — 5000원이에요.","색연필과 사인펜은 7000원, 연필과 지우개는 3000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#22','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',3,'error','auto','친구들이 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X04','M2-2-u1-X05']::text[],false,'{"seq":22,"concept":"M2-2-u1-C3","difficulty":3,"kind":"error","stem":"친구들이 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호: 삼천이백오십팔 → 3285","correct":true,"mis_target":"M2-2-u1-X06"},{"t":"하윤: 오천칠백팔 → 5708","mis":"M2-2-u1-X04"},{"t":"시우: 천오백삼십육 → 1536","mis":"M2-2-u1-X05"}],"explanation":["삼천이백오십팔은 3258이에요.","십의 자리 5와 일의 자리 8의 순서를 바꾸면 안 돼요.","그래서 지호가 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#23','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',4,'mc','auto','수 카드 놀이를 해요. 나는 5, 2, 7, 6을, 짝은 7, 1, 3, 8을 뒤집었어요. 둘 다 가장 큰 네 자리 수를 만들고 더 큰 수를 만든 사람이 1점을 얻어요. 1점을 얻는 사람은 누구인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],false,'{"seq":23,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 놀이를 해요. 나는 5, 2, 7, 6을, 짝은 7, 1, 3, 8을 뒤집었어요. 둘 다 가장 큰 네 자리 수를 만들고 더 큰 수를 만든 사람이 1점을 얻어요. 1점을 얻는 사람은 누구인가요?","options":[{"t":"짝","correct":true},{"t":"나","mis":"M2-2-u1-X15"},{"t":"비겨요","mis":"M2-2-u1-X16"}],"explanation":["나는 7652, 짝은 8731을 만들 수 있어요.","천의 자리부터 견주면 7652 < 8731예요.","그래서 짝이 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#24','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',4,'mc','auto','세미의 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 저금하면 처음으로 5000원보다 많아지는 달은 언제인가요?',ARRAY['M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"세미의 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 저금하면 처음으로 5000원보다 많아지는 달은 언제인가요?","options":[{"t":"12월","correct":true},{"t":"10월","mis":"M2-2-u1-X15"},{"t":"11월","mis":"M2-2-u1-X15"}],"explanation":["9월 2360원, 10월 3360원, 11월 4360원, 12월 5360원 — 1000씩 뛰어 세요.","5000원보다 처음 많아지는 것은 5360원인 12월이에요.","「처음으로 많아지는」 달을 묻는 것인지 꼭 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_c#25','math',2,2,'u1','','tb_g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',4,'essay','teacher','5107, 6714, 5400을 작은 수부터 차례로 쓰고, 어떻게 비교했는지 자리 이름을 넣어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C6","difficulty":4,"kind":"essay","stem":"5107, 6714, 5400을 작은 수부터 차례로 쓰고, 어떻게 비교했는지 자리 이름을 넣어 설명해 보세요.","answer_guide":{"answer":"5107, 5400, 6714. 천의 자리를 먼저 비교하면 6714가 가장 크다. 천의 자리가 같은 5107과 5400은 백의 자리를 비교하여 1 < 4이므로 5107이 더 작다.","scoring_points":["세 수를 작은 수부터 바르게 썼는가","천의 자리부터 비교했다고 썼는가","천의 자리가 같은 두 수는 백의 자리로 비교했다고 썼는가"]},"explanation":["세 수도 두 수를 견줄 때처럼 높은 자리부터 견주어요.","천의 자리로 가장 큰 수를 먼저 찾아요.","남은 두 수는 백의 자리로 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#1','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',1,'mc','auto','연을 천 모형으로 나타냈어요. 수를 바르게 쓰고 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07']::text[],false,'{"seq":1,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"연을 천 모형으로 나타냈어요. 수를 바르게 쓰고 읽은 것은 어느 것인가요?","options":[{"t":"6000 — 육천","correct":true},{"t":"600 — 육백","mis":"M2-2-u1-X03"},{"t":"6000 — 육영영영","mis":"M2-2-u1-X07"}],"explanation":["천 모형 하나는 1000이에요.","천 모형 6개는 1000이 6개 — 6000, 「육천」이에요.","천 모형과 백 모형을 헷갈리지 않아요."],"asset":{"type":"blocks4","th":6,"h":0,"t":0,"o":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#2','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X06']::text[],false,'{"seq":2,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"1536","correct":true},{"t":"1000500306","mis":"M2-2-u1-X05"},{"t":"1563","mis":"M2-2-u1-X06"}],"explanation":["천 모형 1개, 백 모형 5개, 십 모형 3개, 일 모형 6개예요.","천·백·십·일의 자리에 1, 5, 3, 6 — 1536이에요.","1536 = 1000 + 500 + 30 + 6예요."],"asset":{"type":"blocks4","th":1,"h":5,"t":3,"o":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#3','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',1,'mc','auto','7057을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X04']::text[],false,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"7057을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"칠천오십칠","correct":true},{"t":"칠천영백오십칠","mis":"M2-2-u1-X07"},{"t":"칠천오백칠","mis":"M2-2-u1-X04"}],"explanation":["높은 자리부터 숫자 뒤에 자리 이름을 붙여 읽어요.","7057은 「칠천오십칠」이라고 읽어요.","0인 자리는 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#4','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',1,'mc','auto','9907에서 일의 자리 숫자 7이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08']::text[],false,'{"seq":4,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"9907에서 일의 자리 숫자 7이 나타내는 값은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"7000","mis":"M2-2-u1-X08"},{"t":"700","mis":"M2-2-u1-X08"}],"explanation":["9907에서 7은 일의 자리 숫자예요.","일의 자리 숫자 7은 7을 나타내요.","숫자가 놓인 자리를 보고 값을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#5','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',1,'sa','auto','1217부터 1000씩 2번 뛰어 센 수는 얼마인가요?','{}'::text[],false,'{"seq":5,"concept":"M2-2-u1-C5","difficulty":1,"kind":"sa","stem":"1217부터 1000씩 2번 뛰어 센 수는 얼마인가요?","answer":["3217"],"explanation":["1000씩 뛰면 천의 자리 숫자만 1씩 커져요.","1217 → 2217 → 3217이에요.","백·십·일의 자리 숫자 2, 1, 7은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#6','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',1,'mc','auto','1999 ○ 2005 — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M2-2-u1-X14','M2-2-u1-X13']::text[],false,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"1999 ○ 2005 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리부터 차례로 견주어요.","천의 자리에서 처음 달라요 — 1은 2보다 작아요.","그래서 1999 < 2005예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#7','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C1',1,'sa','auto','연이 한 상자에 100개씩 10상자 있어요. 연은 모두 몇 개인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u1-C1","difficulty":1,"kind":"sa","stem":"연이 한 상자에 100개씩 10상자 있어요. 연은 모두 몇 개인가요?","answer":["1000"],"explanation":["100개씩 10상자예요.","100이 10개이면 1000이에요.","그래서 연은 1000개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#8','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',1,'mc','auto','태극기는 1개에 1000원이에요. 태극기 2개를 사려면 얼마를 내야 하나요?',ARRAY['M2-2-u1-X03']::text[],false,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"태극기는 1개에 1000원이에요. 태극기 2개를 사려면 얼마를 내야 하나요?","options":[{"t":"2000원","correct":true},{"t":"200원","mis":"M2-2-u1-X03"},{"t":"1002원","mis":"M2-2-u1-X03"}],"explanation":["1000원씩 2번 세어요.","1000이 2개이면 2000 — 2000원이에요.","2000은 「이천」이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#9','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',2,'mc','auto','4352를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":9,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"4352를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4000 + 300 + 50 + 2","correct":true},{"t":"4 + 3 + 5 + 2","mis":"M2-2-u1-X09"},{"t":"4000 + 30 + 50 + 2","mis":"M2-2-u1-X08"}],"explanation":["4352는 1000이 4개, 100이 3개, 10이 5개, 1이 2개예요.","그래서 4352 = 4000 + 300 + 50 + 2예요.","숫자만 더하면 안 돼요 — 자리마다 나타내는 값을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#10','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',2,'mc','auto','자릿값 카드 찾기 놀이를 해요. 선생님이 3819에서 십의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],false,'{"seq":10,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"자릿값 카드 찾기 놀이를 해요. 선생님이 3819에서 십의 자리 숫자를 가리켰어요. 어떤 카드를 들어야 하나요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X09"},{"t":"1000","mis":"M2-2-u1-X08"}],"explanation":["3819에서 십의 자리 숫자는 1이에요.","십의 자리 숫자 1은 10을 나타내요.","그래서 10이 적힌 카드를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#11','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',2,'mc','auto','1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],false,'{"seq":11,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"3500","correct":true},{"t":"2600","mis":"M2-2-u1-X11"},{"t":"2510","mis":"M2-2-u1-X11"}],"explanation":["1000씩 뛰면 천의 자리 숫자가 1씩 커져요.","빈칸에는 3500이 들어가요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[1500,2500,null,4500],"step":1000}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#12','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',2,'sa','auto','1000이 7개, 100이 0개, 10이 5개, 1이 7개인 수는 얼마인가요?','{}'::text[],false,'{"seq":12,"concept":"M2-2-u1-C3","difficulty":2,"kind":"sa","stem":"1000이 7개, 100이 0개, 10이 5개, 1이 7개인 수는 얼마인가요?","answer":["7057"],"explanation":["개수를 천의 자리부터 차례로 써요 — 7, 0, 5, 7.","그래서 7057이에요.","개수가 0인 자리에는 0을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#13','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',2,'mc','auto','2180, 1422, 2046 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":13,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"2180, 1422, 2046 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"1422","correct":true},{"t":"2046","mis":"M2-2-u1-X13"},{"t":"2180","mis":"M2-2-u1-X15"}],"explanation":["천의 자리부터 차례로 견주어요.","가장 작은 수는 1422예요.","천의 자리가 같으면 백의 자리를 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#14','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C7',2,'sa','auto','4000을 1000 3개와 100 몇 개로 나타내요. 100은 몇 개가 있어야 하나요?','{}'::text[],false,'{"seq":14,"concept":"M2-2-u1-C7","difficulty":2,"kind":"sa","stem":"4000을 1000 3개와 100 몇 개로 나타내요. 100은 몇 개가 있어야 하나요?","answer":["10","10개"],"explanation":["1000이 3개는 3000이에요.","나머지 1000은 100이 10개예요.","그래서 100을 10개 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#15','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',2,'mc','auto','기념품 손수건이 4392장 있어요. 물건의 수를 세어 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u1-X17']::text[],false,'{"seq":15,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"기념품 손수건이 4392장 있어요. 물건의 수를 세어 바르게 말한 것은 어느 것인가요?","options":[{"t":"사천삼백아흔두 장","correct":true},{"t":"사천삼백구십이 장","mis":"M2-2-u1-X17"},{"t":"사천셋백아흔두 장","mis":"M2-2-u1-X17"}],"explanation":["수 4392는 「사천삼백구십이」라고 읽어요.","물건을 셀 때는 「사천삼백아흔두 장」이라고 말해요.","읽는 말과 세는 말을 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#16','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',2,'mc','auto','독도 이야기책의 네 사건(1982년 · 1999년 · 2005년 · 2010년)을 일어난 순서대로 놓아요. 세 번째로 일어난 일은 어느 것인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":16,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"독도 이야기책의 네 사건(1982년 · 1999년 · 2005년 · 2010년)을 일어난 순서대로 놓아요. 세 번째로 일어난 일은 어느 것인가요?","options":[{"t":"2005년 — 독도를 여행할 수 있게 되었어요","correct":true},{"t":"2010년 — 독도를 여행한 사람들에게 명예 주민증을 만들어 주기 시작했어요","mis":"M2-2-u1-X13"},{"t":"1999년 — 독도 천연 보호 구역으로 이름을 바꾸어 보호하기 시작했어요","mis":"M2-2-u1-X15"}],"explanation":["연도는 수가 작을수록 오래전, 클수록 최근이에요.","천의 자리부터 견주면 1982 < 1999 < 2005 < 2010이에요.","그래서 세 번째로 일어난 일은 2005년이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#17','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',3,'mc','auto','수 카드 0, 2, 5, 7을 한 번씩만 써서 네 자리 수를 만들어요. 십의 자리 숫자가 50을 나타내는 수 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X16']::text[],false,'{"seq":17,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"수 카드 0, 2, 5, 7을 한 번씩만 써서 네 자리 수를 만들어요. 십의 자리 숫자가 50을 나타내는 수 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"7250","correct":true},{"t":"7520","mis":"M2-2-u1-X08"},{"t":"2750","mis":"M2-2-u1-X16"}],"explanation":["십의 자리에 5를 놓아요.","남은 7, 2, 0을 큰 수부터 천·백·일의 자리에 놓으면 7250이에요.","7520은 5가 백의 자리라서 500을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#18','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',3,'mc','auto','1부터 9까지의 수 가운데 4518 < □618 의 □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X13']::text[],false,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"1부터 9까지의 수 가운데 4518 < □618 의 □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"5개","mis":"M2-2-u1-X13"},{"t":"7개","mis":"M2-2-u1-X13"}],"explanation":["□에 4를 넣으면 4618 — 4518보다 커요.","□는 4, 5, 6, 7, 8, 9예요.","그래서 모두 6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#19','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',3,'mc','auto','9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":19,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"9901부터 9999까지의 수 배열표의 한 부분이에요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"9978","correct":true},{"t":"9987","mis":"M2-2-u1-X12"},{"t":"9969","mis":"M2-2-u1-X12"}],"explanation":["오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요.","빈칸 둘레의 수에서 오른쪽은 1씩, 아래는 10씩 세어 보면 9978이에요.","두 방향으로 확인하면 틀리지 않아요."],"asset":{"type":"numgrid","rows":[[9976,9977,null,9979],[9986,9987,9988,9989],[9996,9997,9998,9999]],"name":"수 배열표","q":[0,2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#20','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C7',3,'mc','auto','지아가 천 원짜리 3장과 100원짜리 동전 8개를 냈어요. 이 돈을 100원짜리 동전으로만 바꾸면 몇 개인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X04']::text[],false,'{"seq":20,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"지아가 천 원짜리 3장과 100원짜리 동전 8개를 냈어요. 이 돈을 100원짜리 동전으로만 바꾸면 몇 개인가요?","options":[{"t":"38개","correct":true},{"t":"11개","mis":"M2-2-u1-X03"},{"t":"308개","mis":"M2-2-u1-X04"}],"explanation":["천 원짜리 1장은 100원짜리 10개예요.","천 원짜리 3장은 100원짜리 30개 — 8개를 더하면 38개예요.","3800은 100이 38개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#21','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',3,'mc','auto','친구의 생일 선물을 5000원만큼 사려고 해요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],false,'{"seq":21,"concept":"M2-2-u1-C2","difficulty":3,"kind":"mc","stem":"친구의 생일 선물을 5000원만큼 사려고 해요. (공책 1000원 · 색연필 3000원 · 사인펜 4000원 · 지우개 1000원 · 연필 2000원 · 필통 4000원 · 고무찰흙 2000원) 두 가지를 골라 꼭 5000원이 되는 것은 어느 것인가요?","options":[{"t":"고무찰흙과 색연필","correct":true},{"t":"필통과 연필","mis":"M2-2-u1-X15"},{"t":"공책과 연필","mis":"M2-2-u1-X12"}],"explanation":["고무찰흙 2000원과 색연필 3000원 — 1000원이 2장과 3장이에요.","1000원이 모두 5장 — 5000원이에요.","필통과 연필은 6000원, 공책과 연필은 3000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#22','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',3,'error','auto','친구들이 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X06']::text[],false,'{"seq":22,"concept":"M2-2-u1-C3","difficulty":3,"kind":"error","stem":"친구들이 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"라온: 이천오십일 → 251","correct":true,"mis_target":"M2-2-u1-X04"},{"t":"나은: 칠천오십칠 → 7057","mis":"M2-2-u1-X04"},{"t":"세아: 사천삼백구십이 → 4392","mis":"M2-2-u1-X06"}],"explanation":["이천오십일은 2051이에요.","백의 자리에 0을 빠뜨리면 세 자리 수가 돼요.","그래서 라온이가 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#23','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',4,'mc','auto','수 카드 놀이를 해요. 나는 6, 3, 9, 4를, 짝은 5, 8, 2, 9를 뒤집었어요. 둘 다 가장 작은 네 자리 수를 만들고 더 작은 수를 만든 사람이 1점을 얻어요. 1점을 얻는 사람은 누구인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],false,'{"seq":23,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 놀이를 해요. 나는 6, 3, 9, 4를, 짝은 5, 8, 2, 9를 뒤집었어요. 둘 다 가장 작은 네 자리 수를 만들고 더 작은 수를 만든 사람이 1점을 얻어요. 1점을 얻는 사람은 누구인가요?","options":[{"t":"짝","correct":true},{"t":"나","mis":"M2-2-u1-X15"},{"t":"비겨요","mis":"M2-2-u1-X16"}],"explanation":["나는 3469, 짝은 2589를 만들 수 있어요.","천의 자리부터 견주면 3469 > 2589예요.","그래서 짝이 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#24','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',4,'mc','auto','세미의 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 저금하면 처음으로 4500원보다 많아지는 달은 언제인가요?',ARRAY['M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"세미의 기부 통장에 9월에 2360원이 있어요. 한 달에 1000원씩 저금하면 처음으로 4500원보다 많아지는 달은 언제인가요?","options":[{"t":"12월","correct":true},{"t":"10월","mis":"M2-2-u1-X15"},{"t":"11월","mis":"M2-2-u1-X15"}],"explanation":["9월 2360원, 10월 3360원, 11월 4360원, 12월 5360원 — 1000씩 뛰어 세요.","4500원보다 처음 많아지는 것은 5360원인 12월이에요.","「처음으로 많아지는」 달을 묻는 것인지 꼭 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u1_review_d#25','math',2,2,'u1','','tb_g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',4,'essay','teacher','6419 < □518 에서 □ 안에 6이 들어갈 수 있는지 쓰고, 까닭을 자리 이름을 넣어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C6","difficulty":4,"kind":"essay","stem":"6419 < □518 에서 □ 안에 6이 들어갈 수 있는지 쓰고, 까닭을 자리 이름을 넣어 설명해 보세요.","answer_guide":{"answer":"들어갈 수 있다. □가 6이면 6518이고 천의 자리 숫자가 같으므로 백의 자리를 비교한다. 5가 4보다 크므로 6518 > 6419이다.","scoring_points":["6이 들어갈 수 있다고 판단했는가","천의 자리가 같으면 백의 자리를 비교한다고 썼는가","6518 > 6419로 바르게 나타냈는가"]},"explanation":["천의 자리가 같아도 끝난 것이 아니에요.","다음 자리인 백의 자리를 견주어요.","같은 숫자가 들어가는 경우도 꼭 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
